"""MLIR core IR data structures."""
from __future__ import annotations
from typing import List, Optional, Dict, Any, Callable
from abc import ABC, abstractmethod
from enum import Enum, auto


class MLIRContext:
    """Global context for MLIR objects."""

    def __init__(self) -> None:
        self._registered_dialects: Dict[str, Dialect] = {}
        self._type_cache: Dict[str, Type] = {}

    def register_dialect(self, dialect: Dialect) -> None:
        self._registered_dialects[dialect.name] = dialect

    def get_dialect(self, name: str) -> Optional[Dialect]:
        return self._registered_dialects.get(name)

    def get_or_create_type(self, key: str, factory: Callable) -> Type:
        if key not in self._type_cache:
            self._type_cache[key] = factory()
        return self._type_cache[key]


class Dialect:
    """Base class for MLIR dialects."""

    def __init__(self, name: str, context: MLIRContext) -> None:
        self.name = name
        self.context = context
        self._operations: Dict[str, type] = {}
        context.register_dialect(self)

    def register_operation(self, op_class: type) -> None:
        self._operations[op_class.operation_name()] = op_class

    def get_operation(self, name: str) -> Optional[type]:
        return self._operations.get(name)


class Type(ABC):
    """Base class for all MLIR types."""

    @abstractmethod
    def __str__(self) -> str:
        pass

    @abstractmethod
    def __eq__(self, other: object) -> bool:
        pass

    @abstractmethod
    def __hash__(self) -> int:
        pass


class IntegerType(Type):
    """Fixed-width integer type."""

    class SignednessSemantics(Enum):
        SIGNLESS = auto()
        SIGNED = auto()
        UNSIGNED = auto()

    def __init__(self, width: int,
                 signedness: SignednessSemantics = SignednessSemantics.SIGNLESS) -> None:
        self._width = width
        self._signedness = signedness

    @property
    def width(self) -> int:
        return self._width

    @property
    def signedness(self) -> IntegerType.SignednessSemantics:
        return self._signedness

    def is_signless(self) -> bool:
        return self._signedness == IntegerType.SignednessSemantics.SIGNLESS

    def is_signed(self) -> bool:
        return self._signedness == IntegerType.SignednessSemantics.SIGNED

    def is_unsigned(self) -> bool:
        return self._signedness == IntegerType.SignednessSemantics.UNSIGNED

    def __str__(self) -> str:
        if self.is_signless():
            return f"i{self._width}"
        elif self.is_signed():
            return f"si{self._width}"
        return f"ui{self._width}"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, IntegerType):
            return False
        return self._width == other._width and self._signedness == other._signedness

    def __hash__(self) -> int:
        return hash((self._width, self._signedness))


class FloatType(Type):
    """Floating-point type."""

    def __init__(self, width: int) -> None:
        if width not in (16, 32, 64, 80, 128):
            raise ValueError(f"Unsupported float width: {width}")
        self._width = width

    @property
    def width(self) -> int:
        return self._width

    def __str__(self) -> str:
        return f"f{self._width}"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, FloatType):
            return False
        return self._width == other._width

    def __hash__(self) -> int:
        return hash(("float", self._width))


class IndexType(Type):
    """Index type for dimension values."""

    def __str__(self) -> str:
        return "index"

    def __eq__(self, other: object) -> bool:
        return isinstance(other, IndexType)

    def __hash__(self) -> int:
        return hash("index")


class NoneType(Type):
    """None type representing absence of value."""

    def __str__(self) -> str:
        return "none"

    def __eq__(self, other: object) -> bool:
        return isinstance(other, NoneType)

    def __hash__(self) -> int:
        return hash("none")


class OpaqueType(Type):
    """Dialect-defined type printed verbatim, e.g. `!seq.clock`."""

    def __init__(self, dialect: str, mnemonic: str) -> None:
        self._dialect = dialect
        self._mnemonic = mnemonic

    @property
    def dialect(self) -> str:
        return self._dialect

    @property
    def mnemonic(self) -> str:
        return self._mnemonic

    def __str__(self) -> str:
        return f"!{self._dialect}.{self._mnemonic}"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, OpaqueType):
            return False
        return self._dialect == other._dialect and self._mnemonic == other._mnemonic

    def __hash__(self) -> int:
        return hash(("opaque", self._dialect, self._mnemonic))


class MemRefType(Type):
    """Multi-dimensional memory reference type."""

    def __init__(self, shape: List[int], element_type: Type,
                 memory_space: int = 0) -> None:
        self._shape = list(shape)
        self._element_type = element_type
        self._memory_space = memory_space

    @property
    def shape(self) -> List[int]:
        return self._shape

    @property
    def element_type(self) -> Type:
        return self._element_type

    @property
    def rank(self) -> int:
        return len(self._shape)

    def has_static_shape(self) -> bool:
        return all(d >= 0 for d in self._shape)

    def get_num_elements(self) -> int:
        if not self.has_static_shape():
            raise ValueError("Cannot compute num elements for dynamic shape")
        result = 1
        for d in self._shape:
            result *= d
        return result

    def __str__(self) -> str:
        dims = "x".join("?" if d < 0 else str(d) for d in self._shape)
        return f"memref<{dims}x{self._element_type}>"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, MemRefType):
            return False
        return (self._shape == other._shape and
                self._element_type == other._element_type and
                self._memory_space == other._memory_space)

    def __hash__(self) -> int:
        return hash(("memref", tuple(self._shape), self._element_type))


class TensorType(Type):
    """Multi-dimensional tensor type."""

    def __init__(self, shape: List[int], element_type: Type) -> None:
        self._shape = list(shape)
        self._element_type = element_type

    @property
    def shape(self) -> List[int]:
        return self._shape

    @property
    def element_type(self) -> Type:
        return self._element_type

    @property
    def rank(self) -> int:
        return len(self._shape)

    def has_static_shape(self) -> bool:
        return all(d >= 0 for d in self._shape)

    def __str__(self) -> str:
        dims = "x".join("?" if d < 0 else str(d) for d in self._shape)
        return f"tensor<{dims}x{self._element_type}>"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, TensorType):
            return False
        return self._shape == other._shape and self._element_type == other._element_type

    def __hash__(self) -> int:
        return hash(("tensor", tuple(self._shape), self._element_type))


class FunctionType(Type):
    """Function type with inputs and results."""

    def __init__(self, inputs: List[Type], results: List[Type]) -> None:
        self._inputs = list(inputs)
        self._results = list(results)

    @property
    def inputs(self) -> List[Type]:
        return self._inputs

    @property
    def results(self) -> List[Type]:
        return self._results

    def __str__(self) -> str:
        inputs_str = ", ".join(str(t) for t in self._inputs)
        if len(self._results) == 1:
            return f"({inputs_str}) -> {self._results[0]}"
        results_str = ", ".join(str(t) for t in self._results)
        return f"({inputs_str}) -> ({results_str})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, FunctionType):
            return False
        return self._inputs == other._inputs and self._results == other._results

    def __hash__(self) -> int:
        return hash(("func", tuple(self._inputs), tuple(self._results)))


class Attribute(ABC):
    """Base class for all MLIR attributes."""

    @abstractmethod
    def __str__(self) -> str:
        pass


class IntegerAttr(Attribute):
    def __init__(self, value: int, type: IntegerType) -> None:
        self._value = value
        self._type = type

    @property
    def value(self) -> int:
        return self._value

    @property
    def type(self) -> IntegerType:
        return self._type

    def __str__(self) -> str:
        return f"{self._value} : {self._type}"


class FloatAttr(Attribute):
    def __init__(self, value: float, type: FloatType) -> None:
        self._value = value
        self._type = type

    @property
    def value(self) -> float:
        return self._value

    @property
    def type(self) -> FloatType:
        return self._type

    def __str__(self) -> str:
        return f"{self._value:g} : {self._type}"


class StringAttr(Attribute):
    def __init__(self, value: str) -> None:
        self._value = value

    @property
    def value(self) -> str:
        return self._value

    def __str__(self) -> str:
        escaped = self._value.replace("\\", "\\\\").replace('"', '\\"')
        return f'"{escaped}"'


class ArrayAttr(Attribute):
    def __init__(self, elements: List[Attribute]) -> None:
        self._elements = list(elements)

    @property
    def elements(self) -> List[Attribute]:
        return self._elements

    def __len__(self) -> int:
        return len(self._elements)

    def __getitem__(self, index: int) -> Attribute:
        return self._elements[index]

    def __str__(self) -> str:
        return "[" + ", ".join(str(e) for e in self._elements) + "]"


class DenseElementsAttr(Attribute):
    def __init__(self, type: TensorType, values: List[Any]) -> None:
        self._type = type
        self._values = list(values)

    @property
    def type(self) -> TensorType:
        return self._type

    @property
    def values(self) -> List[Any]:
        return self._values

    def __str__(self) -> str:
        vals = ", ".join(str(v) for v in self._values)
        return f"dense<[{vals}]> : {self._type}"


class Value:
    """Represents an SSA value."""

    def __init__(self, type: Type) -> None:
        self._type = type
        self._uses: List[OpOperand] = []

    @property
    def type(self) -> Type:
        return self._type

    @property
    def uses(self) -> List[OpOperand]:
        return self._uses

    def add_use(self, operand: OpOperand) -> None:
        self._uses.append(operand)

    def remove_use(self, operand: OpOperand) -> None:
        if operand in self._uses:
            self._uses.remove(operand)

    def replace_all_uses_with(self, new_value: Value) -> None:
        for use in list(self._uses):
            use.set_value(new_value)

    def has_one_use(self) -> bool:
        return len(self._uses) == 1

    def use_empty(self) -> bool:
        return len(self._uses) == 0


class BlockArgument(Value):
    """An SSA value produced by entering a block."""

    def __init__(self, type: Type, block: Block, index: int) -> None:
        super().__init__(type)
        self._block = block
        self._index = index

    @property
    def owner(self) -> Block:
        return self._block

    @property
    def arg_number(self) -> int:
        return self._index


class OpResult(Value):
    """An SSA value produced by an operation."""

    def __init__(self, type: Type, owner: Operation, index: int) -> None:
        super().__init__(type)
        self._owner = owner
        self._index = index

    @property
    def owner(self) -> Operation:
        return self._owner

    @property
    def result_number(self) -> int:
        return self._index


class OpOperand:
    """A single use of a value by an operation."""

    def __init__(self, owner: Operation, value: Value, index: int) -> None:
        self._owner = owner
        self._value = value
        self._index = index
        value.add_use(self)

    @property
    def owner(self) -> Operation:
        return self._owner

    @property
    def value(self) -> Value:
        return self._value

    @property
    def index(self) -> int:
        return self._index

    def set_value(self, new_value: Value) -> None:
        self._value.remove_use(self)
        self._value = new_value
        new_value.add_use(self)


class OperationName:
    """The fully qualified name of an operation, e.g. `arith.addi`."""

    def __init__(self, name: str) -> None:
        self._name = name

    @property
    def dialect_name(self) -> str:
        parts = self._name.split(".", 1)
        return parts[0] if len(parts) > 1 else ""

    @property
    def stripped_name(self) -> str:
        parts = self._name.split(".", 1)
        return parts[1] if len(parts) > 1 else self._name

    def __str__(self) -> str:
        return self._name

    def __repr__(self) -> str:
        return f"OperationName({self._name!r})"

    def __eq__(self, other: object) -> bool:
        if isinstance(other, str):
            return self._name == other
        if isinstance(other, OperationName):
            return self._name == other._name
        return False

    def __hash__(self) -> int:
        return hash(self._name)


class Operation:
    """Core operation class in MLIR."""

    def __init__(self, name: str, operands: List[Value] = None,
                 result_types: List[Type] = None,
                 attributes: Dict[str, Attribute] = None,
                 regions: List[Region] = None) -> None:
        self._name = OperationName(name)
        self._operands: List[OpOperand] = []
        self._results: List[OpResult] = []
        self._attributes: Dict[str, Attribute] = attributes or {}
        self._regions: List[Region] = regions or []
        self._parent_block: Optional[Block] = None
        self._successors: List[Block] = []
        for i, val in enumerate(operands or []):
            self._operands.append(OpOperand(self, val, i))
        for i, typ in enumerate(result_types or []):
            self._results.append(OpResult(typ, self, i))
        for region in self._regions:
            region._parent_op = self

    @property
    def name(self) -> OperationName:
        return self._name

    @property
    def operands(self) -> List[Value]:
        return [operand.value for operand in self._operands]

    @property
    def num_operands(self) -> int:
        return len(self._operands)

    @property
    def results(self) -> List[OpResult]:
        return self._results

    @property
    def attributes(self) -> Dict[str, Attribute]:
        return self._attributes

    @property
    def regions(self) -> List[Region]:
        return self._regions

    @property
    def successors(self) -> List[Block]:
        return self._successors

    @property
    def parent_block(self) -> Optional[Block]:
        return self._parent_block

    @property
    def parent_op(self) -> Optional[Operation]:
        if self._parent_block is None:
            return None
        region = self._parent_block.parent_region
        return region.parent_op if region is not None else None

    def get_operand(self, index: int) -> Value:
        return self._operands[index].value

    def set_operand(self, index: int, value: Value) -> None:
        self._operands[index].set_value(value)

    def get_result(self, index: int) -> OpResult:
        return self._results[index]

    def set_attr(self, name: str, attr: Attribute) -> None:
        self._attributes[name] = attr

    def get_attr(self, name: str) -> Optional[Attribute]:
        return self._attributes.get(name)

    def has_trait_terminator(self) -> bool:
        return bool(self._successors) or str(self._name) in (
            "return", "func.return", "cf.br", "cf.cond_br", "hw.output",
        )

    def add_region(self) -> Region:
        region = Region()
        region._parent_op = self
        self._regions.append(region)
        return region

    def erase(self) -> None:
        if self._parent_block:
            self._parent_block.remove_operation(self)
        for operand in self._operands:
            operand.value.remove_use(operand)

    def walk(self, callback: Callable) -> None:
        """Pre-order walk over this operation and everything nested inside it."""
        callback(self)
        for region in self._regions:
            for block in region.blocks:
                for op in list(block.operations):
                    op.walk(callback)

    def __repr__(self) -> str:
        return f"Operation({str(self._name)!r})"


class Region:
    """Contains a list of blocks."""

    def __init__(self) -> None:
        self._blocks: List[Block] = []
        self._parent_op: Optional[Operation] = None

    @property
    def blocks(self) -> List[Block]:
        return self._blocks

    @property
    def parent_op(self) -> Optional[Operation]:
        return self._parent_op

    def add_block(self) -> Block:
        block = Block()
        block._parent_region = self
        self._blocks.append(block)
        return block

    def push_block(self, block: Block) -> Block:
        block._parent_region = self
        self._blocks.append(block)
        return block

    @property
    def entry_block(self) -> Optional[Block]:
        return self._blocks[0] if self._blocks else None

    def empty(self) -> bool:
        return len(self._blocks) == 0


class Block:
    """A basic block containing operations."""

    def __init__(self, arg_types: List[Type] = None) -> None:
        self._arguments: List[BlockArgument] = []
        self._operations: List[Operation] = []
        self._parent_region: Optional[Region] = None
        for i, t in enumerate(arg_types or []):
            self._arguments.append(BlockArgument(t, self, i))

    @property
    def arguments(self) -> List[BlockArgument]:
        return self._arguments

    @property
    def operations(self) -> List[Operation]:
        return self._operations

    @property
    def parent_region(self) -> Optional[Region]:
        return self._parent_region

    @property
    def parent_op(self) -> Optional[Operation]:
        return self._parent_region.parent_op if self._parent_region else None

    def add_argument(self, type: Type) -> BlockArgument:
        arg = BlockArgument(type, self, len(self._arguments))
        self._arguments.append(arg)
        return arg

    def add_operation(self, op: Operation) -> None:
        op._parent_block = self
        self._operations.append(op)

    def insert_operation(self, index: int, op: Operation) -> None:
        op._parent_block = self
        self._operations.insert(index, op)

    def remove_operation(self, op: Operation) -> None:
        self._operations.remove(op)
        op._parent_block = None

    def insert_before(self, new_op: Operation, before: Operation) -> None:
        idx = self._operations.index(before)
        self.insert_operation(idx, new_op)

    def insert_after(self, new_op: Operation, after: Operation) -> None:
        idx = self._operations.index(after) + 1
        self.insert_operation(idx, new_op)

    @property
    def terminator(self) -> Optional[Operation]:
        return self._operations[-1] if self._operations else None

    def successors(self) -> List[Block]:
        term = self.terminator
        return list(term.successors) if term is not None else []

    def empty(self) -> bool:
        return len(self._operations) == 0

"""MLIR textual format parser."""
from __future__ import annotations
from typing import List, Optional, Dict, Tuple
from enum import Enum, auto
from .ir import (
    Operation, Region, Block, Type, IntegerType, FloatType, IndexType,
    MemRefType, TensorType, FunctionType, NoneType, OpaqueType, Attribute,
    IntegerAttr, FloatAttr, StringAttr, ArrayAttr, Value, OpResult, MLIRContext
)


class TokenKind(Enum):
    """Token types for the MLIR lexer."""
    PERCENT = auto()
    AT = auto()
    HASH = auto()
    EQUAL = auto()
    ARROW = auto()
    COLON = auto()
    COMMA = auto()
    LPAREN = auto()
    RPAREN = auto()
    LBRACE = auto()
    RBRACE = auto()
    LBRACKET = auto()
    RBRACKET = auto()
    LANGLE = auto()
    RANGLE = auto()
    INTEGER_LITERAL = auto()
    FLOAT_LITERAL = auto()
    STRING_LITERAL = auto()
    BARE_IDENTIFIER = auto()
    CARET_IDENTIFIER = auto()
    EXCLAIM = auto()
    KEYWORD = auto()
    EOF = auto()
    STAR = auto()
    QUESTION = auto()
    ELLIPSIS = auto()


class Token:
    """A single lexer token."""

    def __init__(self, kind: TokenKind, value: str, line: int, col: int) -> None:
        self.kind = kind
        self.value = value
        self.line = line
        self.col = col

    def __repr__(self) -> str:
        return f"Token({self.kind}, {self.value!r})"


class ParseError(Exception):
    """Error raised during parsing."""

    def __init__(self, message: str, line: int = 0, col: int = 0) -> None:
        self.line = line
        self.col = col
        super().__init__(f"Parse error at {line}:{col}: {message}")


class Lexer:
    """Tokenizer for MLIR textual format."""

    KEYWORDS = frozenset([
        "func", "module", "return", "br", "cond_br", "memref", "tensor",
        "index", "none", "true", "false", "dense", "loc", "attributes"
    ])

    SIMPLE_TOKENS = {
        '%': TokenKind.PERCENT, '@': TokenKind.AT, '#': TokenKind.HASH,
        '=': TokenKind.EQUAL, ':': TokenKind.COLON, ',': TokenKind.COMMA,
        '(': TokenKind.LPAREN, ')': TokenKind.RPAREN,
        '{': TokenKind.LBRACE, '}': TokenKind.RBRACE,
        '[': TokenKind.LBRACKET, ']': TokenKind.RBRACKET,
        '<': TokenKind.LANGLE, '>': TokenKind.RANGLE,
        '*': TokenKind.STAR, '?': TokenKind.QUESTION,
        '!': TokenKind.EXCLAIM,
    }

    def __init__(self, source: str) -> None:
        self._source = source
        self._pos = 0
        self._line = 1
        self._col = 1
        self._tokens: List[Token] = []
        self._tokenize()

    def _peek_char(self) -> str:
        if self._pos >= len(self._source):
            return ""
        return self._source[self._pos]

    def _advance(self) -> str:
        ch = self._source[self._pos]
        self._pos += 1
        if ch == "\n":
            self._line += 1
            self._col = 1
        else:
            self._col += 1
        return ch

    def _skip_whitespace_and_comments(self) -> None:
        while self._pos < len(self._source):
            ch = self._source[self._pos]
            if ch in " \t\r\n":
                self._advance()
            elif (ch == "/" and self._pos + 1 < len(self._source)
                  and self._source[self._pos + 1] == "/"):
                while self._pos < len(self._source) and self._source[self._pos] != "\n":
                    self._advance()
            else:
                break

    def _read_string(self) -> str:
        self._advance()  # consume opening quote
        result = []
        while self._pos < len(self._source):
            ch = self._advance()
            if ch == '"':
                return "".join(result)
            elif ch == '\\':
                next_ch = self._advance()
                if next_ch == 'n':
                    result.append('\n')
                elif next_ch == 't':
                    result.append('\t')
                elif next_ch == '\\':
                    result.append('\\')
                elif next_ch == '"':
                    result.append('"')
                else:
                    result.append(next_ch)
            else:
                result.append(ch)
        raise ParseError("Unterminated string literal", self._line, self._col)

    def _read_number(self) -> Token:
        start = self._pos
        line, col = self._line, self._col
        is_float = False
        if self._source[self._pos] == '-':
            self._advance()
        while self._pos < len(self._source) and self._source[self._pos].isdigit():
            self._advance()
        if self._pos < len(self._source) and self._source[self._pos] == '.':
            is_float = True
            self._advance()
            while self._pos < len(self._source) and self._source[self._pos].isdigit():
                self._advance()
        if self._pos < len(self._source) and self._source[self._pos] in ('e', 'E'):
            is_float = True
            self._advance()
            if self._pos < len(self._source) and self._source[self._pos] in ('+', '-'):
                self._advance()
            while self._pos < len(self._source) and self._source[self._pos].isdigit():
                self._advance()
        value = self._source[start:self._pos]
        kind = TokenKind.FLOAT_LITERAL if is_float else TokenKind.INTEGER_LITERAL
        return Token(kind, value, line, col)

    def _read_identifier(self) -> Token:
        start = self._pos
        line, col = self._line, self._col
        while (self._pos < len(self._source) and
               (self._source[self._pos].isalnum() or self._source[self._pos] in '_$.')):
            self._advance()
        value = self._source[start:self._pos]
        kind = TokenKind.KEYWORD if value in self.KEYWORDS else TokenKind.BARE_IDENTIFIER
        return Token(kind, value, line, col)

    def _split_shape_separator(self, tok: Token, start_pos: int,
                               line: int, col: int) -> bool:
        """Peel the `x` separator out of a shaped-type dimension list.

        `memref<2x?x4xi32>` lexes `4xi32` as a single identifier because `x` is
        a normal identifier character. When an identifier starting with `x`
        directly follows a dimension, emit the separator on its own and re-lex
        the remainder, yielding `4`, `x`, `i32`.
        """
        if len(tok.value) < 2 or tok.value[0] != "x":
            return False
        if not self._tokens or self._tokens[-1].kind not in (
                TokenKind.INTEGER_LITERAL, TokenKind.QUESTION):
            return False
        self._pos = start_pos + 1
        self._col = col + 1
        self._line = line
        self._tokens.append(Token(TokenKind.BARE_IDENTIFIER, "x", line, col))
        return True

    def _tokenize(self) -> None:
        while self._pos < len(self._source):
            self._skip_whitespace_and_comments()
            if self._pos >= len(self._source):
                break
            ch = self._source[self._pos]
            line, col = self._line, self._col
            next_ch = self._source[self._pos + 1] if self._pos + 1 < len(self._source) else ""
            if ch == '-' and next_ch == '>':
                self._advance()
                self._advance()
                self._tokens.append(Token(TokenKind.ARROW, "->", line, col))
            elif ch == '^':
                self._advance()
                start = self._pos
                while (self._pos < len(self._source) and
                       (self._source[self._pos].isalnum() or self._source[self._pos] == '_')):
                    self._advance()
                self._tokens.append(
                    Token(TokenKind.CARET_IDENTIFIER, self._source[start:self._pos], line, col))
            elif ch == '"':
                value = self._read_string()
                self._tokens.append(Token(TokenKind.STRING_LITERAL, value, line, col))
            elif ch.isdigit() or (ch == '-' and next_ch.isdigit()):
                self._tokens.append(self._read_number())
            elif ch.isalpha() or ch == '_':
                start_pos = self._pos
                tok = self._read_identifier()
                if self._split_shape_separator(tok, start_pos, line, col):
                    continue
                self._tokens.append(tok)
            elif ch in self.SIMPLE_TOKENS:
                self._advance()
                self._tokens.append(Token(self.SIMPLE_TOKENS[ch], ch, line, col))
            else:
                self._advance()
        self._tokens.append(Token(TokenKind.EOF, "", self._line, self._col))

    @property
    def tokens(self) -> List[Token]:
        return self._tokens


class Parser:
    """Recursive descent parser for MLIR textual format."""

    def __init__(self, source: str, context: Optional[MLIRContext] = None) -> None:
        self._lexer = Lexer(source)
        self._tokens = self._lexer.tokens
        self._pos = 0
        self._context = context or MLIRContext()
        self._ssa_values: Dict[str, Value] = {}
        self._block_map: Dict[str, Block] = {}

    @property
    def context(self) -> MLIRContext:
        return self._context

    @property
    def ssa_values(self) -> Dict[str, Value]:
        return self._ssa_values

    def _current(self) -> Token:
        return self._tokens[self._pos]

    def _peek(self) -> Token:
        if self._pos + 1 < len(self._tokens):
            return self._tokens[self._pos + 1]
        return self._tokens[-1]

    def _advance(self) -> Token:
        tok = self._tokens[self._pos]
        self._pos += 1
        return tok

    def _expect(self, kind: TokenKind) -> Token:
        tok = self._current()
        if tok.kind != kind:
            raise ParseError(f"Expected {kind}, got {tok.kind}", tok.line, tok.col)
        return self._advance()

    def _match(self, kind: TokenKind) -> Optional[Token]:
        if self._current().kind == kind:
            return self._advance()
        return None

    def parse_module(self) -> Operation:
        """Parse a top-level module."""
        if self._current().value == "module":
            self._advance()
        region = self._parse_region()
        module_op = Operation("builtin.module", regions=[region])
        return module_op

    def _parse_region(self) -> Region:
        self._expect(TokenKind.LBRACE)
        region = Region()
        while self._current().kind != TokenKind.RBRACE:
            block = self._parse_block()
            region._blocks.append(block)
            block._parent_region = region
        self._expect(TokenKind.RBRACE)
        return region

    def _parse_block(self) -> Block:
        block = Block()
        if self._current().kind == TokenKind.CARET_IDENTIFIER:
            label = self._advance().value
            self._block_map[label] = block
            if self._match(TokenKind.LPAREN):
                while self._current().kind != TokenKind.RPAREN:
                    self._expect(TokenKind.PERCENT)
                    name = self._advance().value
                    self._expect(TokenKind.COLON)
                    arg_type = self._parse_type()
                    arg = block.add_argument(arg_type)
                    self._ssa_values[name] = arg
                    self._match(TokenKind.COMMA)
                self._expect(TokenKind.RPAREN)
            self._expect(TokenKind.COLON)
        while (self._current().kind != TokenKind.RBRACE and
               self._current().kind != TokenKind.CARET_IDENTIFIER and
               self._current().kind != TokenKind.EOF):
            op = self._parse_operation()
            block.add_operation(op)
        return block

    def _parse_operation(self) -> Operation:
        result_names: List[str] = []
        if self._current().kind == TokenKind.PERCENT:
            result_names = self._parse_result_list()
            self._expect(TokenKind.EQUAL)
        op_name = self._parse_operation_name()
        attrs: Dict[str, Attribute] = {}
        if self._current().kind == TokenKind.AT:
            self._advance()
            sym_name = self._advance().value
            attrs["sym_name"] = StringAttr(sym_name)
        block_args: List[Tuple[str, Type]] = []
        if op_name in ("func.func", "builtin.func"):
            block_args = self._parse_func_args()
            operands: List[Value] = []
        else:
            operands = self._parse_operand_list()
        while self._current().kind in (TokenKind.INTEGER_LITERAL, TokenKind.FLOAT_LITERAL):
            tok = self._advance()
            if tok.kind == TokenKind.INTEGER_LITERAL:
                attrs.setdefault("value", IntegerAttr(int(tok.value), IntegerType(64)))
            self._match(TokenKind.COMMA)
        successors = self._parse_optional_successors()
        if self._current().kind == TokenKind.ARROW:
            self._advance()
            result_types = [self._parse_type()]
        else:
            result_types = []
        regions: List[Region] = []
        if (self._current().kind == TokenKind.LBRACE and
                op_name not in ("return", "cf.br", "cf.cond_br")):
            for arg_name, arg_type in block_args:
                self._ssa_values[arg_name] = Value(arg_type)
            regions.append(self._parse_region())
        if self._current().kind == TokenKind.COLON:
            self._advance()
            result_types = self._parse_function_type_or_type_list()
        op = Operation(op_name, operands=operands, result_types=result_types,
                       attributes=attrs, regions=regions)
        op._successors = successors
        for i, name in enumerate(result_names):
            if i < len(op.results):
                self._ssa_values[name] = op.get_result(i)
        return op

    def _parse_func_args(self) -> List[Tuple[str, Type]]:
        args: List[Tuple[str, Type]] = []
        if not self._match(TokenKind.LPAREN):
            return args
        while self._current().kind != TokenKind.RPAREN:
            self._expect(TokenKind.PERCENT)
            name = self._advance().value
            self._expect(TokenKind.COLON)
            arg_type = self._parse_type()
            args.append((name, arg_type))
            self._match(TokenKind.COMMA)
        self._expect(TokenKind.RPAREN)
        return args

    def _parse_result_list(self) -> List[str]:
        names: List[str] = []
        while self._current().kind == TokenKind.PERCENT:
            self._advance()
            names.append(self._advance().value)
            if not self._match(TokenKind.COMMA):
                break
        return names

    def _parse_operation_name(self) -> str:
        return self._advance().value

    def _parse_operand_list(self) -> List[Value]:
        operands: List[Value] = []
        if self._match(TokenKind.LPAREN):
            while self._current().kind != TokenKind.RPAREN:
                self._expect(TokenKind.PERCENT)
                name = self._advance().value
                if name in self._ssa_values:
                    operands.append(self._ssa_values[name])
                self._match(TokenKind.COMMA)
            self._expect(TokenKind.RPAREN)
        else:
            # Leading bare keywords such as the `sgt` predicate of arith.cmpi.
            while self._current().kind in (TokenKind.BARE_IDENTIFIER, TokenKind.KEYWORD):
                self._advance()
                self._match(TokenKind.COMMA)
            while self._current().kind == TokenKind.PERCENT:
                self._advance()
                name = self._advance().value
                if name in self._ssa_values:
                    operands.append(self._ssa_values[name])
                if not self._match(TokenKind.COMMA):
                    break
        return operands

    def _parse_optional_successors(self) -> List[Block]:
        successors: List[Block] = []
        while self._current().kind == TokenKind.CARET_IDENTIFIER:
            if self._peek().kind == TokenKind.COLON:
                break
            label = self._advance().value
            if label in self._block_map:
                successors.append(self._block_map[label])
            self._match(TokenKind.COMMA)
        return successors

    def _parse_optional_attributes(self) -> Dict[str, Attribute]:
        attrs: Dict[str, Attribute] = {}
        if not self._match(TokenKind.LBRACE):
            return attrs
        while self._current().kind != TokenKind.RBRACE:
            key = self._advance().value
            self._expect(TokenKind.EQUAL)
            value = self._parse_attribute_value()
            attrs[key] = value
            self._match(TokenKind.COMMA)
        self._expect(TokenKind.RBRACE)
        return attrs

    def _parse_attribute_value(self) -> Attribute:
        tok = self._current()
        if tok.kind == TokenKind.INTEGER_LITERAL:
            self._advance()
            int_val = int(tok.value)
            if self._match(TokenKind.COLON):
                attr_type = self._parse_type()
                if isinstance(attr_type, IntegerType):
                    return IntegerAttr(int_val, attr_type)
            return IntegerAttr(int_val, IntegerType(64))
        elif tok.kind == TokenKind.FLOAT_LITERAL:
            self._advance()
            float_val = float(tok.value)
            if self._match(TokenKind.COLON):
                attr_type = self._parse_type()
                if isinstance(attr_type, FloatType):
                    return FloatAttr(float_val, attr_type)
            return FloatAttr(float_val, FloatType(64))
        elif tok.kind == TokenKind.STRING_LITERAL:
            self._advance()
            return StringAttr(tok.value)
        else:
            self._advance()
            return StringAttr(tok.value)

    def _parse_type(self) -> Type:
        tok = self._current()
        if tok.kind == TokenKind.EXCLAIM:
            return self._parse_opaque_type()
        if tok.kind in (TokenKind.BARE_IDENTIFIER, TokenKind.KEYWORD):
            name = tok.value
            if name.startswith("i") and name[1:].isdigit():
                self._advance()
                return IntegerType(int(name[1:]))
            elif name.startswith("f") and name[1:].isdigit():
                self._advance()
                return FloatType(int(name[1:]))
            elif name == "index":
                self._advance()
                return IndexType()
            elif name == "none":
                self._advance()
                return NoneType()
            elif name == "memref":
                return self._parse_memref_type()
            elif name == "tensor":
                return self._parse_tensor_type()
            else:
                self._advance()
                return IndexType()
        elif tok.kind == TokenKind.LPAREN:
            return self._parse_function_type()
        self._advance()
        return IndexType()

    def _parse_opaque_type(self) -> Type:
        self._expect(TokenKind.EXCLAIM)
        name = self._advance().value
        if "." in name:
            dialect, mnemonic = name.split(".", 1)
        else:
            dialect, mnemonic = name, ""
        return OpaqueType(dialect, mnemonic)

    def _parse_memref_type(self) -> MemRefType:
        self._advance()  # consume 'memref'
        self._expect(TokenKind.LANGLE)
        shape = self._parse_dimension_list()
        element_type = self._parse_type()
        self._expect(TokenKind.RANGLE)
        return MemRefType(shape, element_type)

    def _parse_tensor_type(self) -> TensorType:
        self._advance()  # consume 'tensor'
        self._expect(TokenKind.LANGLE)
        shape = self._parse_dimension_list()
        element_type = self._parse_type()
        self._expect(TokenKind.RANGLE)
        return TensorType(shape, element_type)

    def _parse_dimension_list(self) -> List[int]:
        dims: List[int] = []
        while True:
            if self._current().kind == TokenKind.QUESTION:
                self._advance()
                dims.append(-1)
            elif self._current().kind == TokenKind.INTEGER_LITERAL:
                dims.append(int(self._advance().value))
            else:
                break
            if self._current().value == "x":
                self._advance()
            else:
                break
        return dims

    def _parse_function_type(self) -> FunctionType:
        self._expect(TokenKind.LPAREN)
        inputs: List[Type] = []
        while self._current().kind != TokenKind.RPAREN:
            inputs.append(self._parse_type())
            self._match(TokenKind.COMMA)
        self._expect(TokenKind.RPAREN)
        self._expect(TokenKind.ARROW)
        results: List[Type] = []
        if self._match(TokenKind.LPAREN):
            while self._current().kind != TokenKind.RPAREN:
                results.append(self._parse_type())
                self._match(TokenKind.COMMA)
            self._expect(TokenKind.RPAREN)
        else:
            results.append(self._parse_type())
        return FunctionType(inputs, results)

    def _parse_function_type_or_type_list(self) -> List[Type]:
        if self._current().kind == TokenKind.LPAREN:
            ft = self._parse_function_type()
            return ft.results
        types = [self._parse_type()]
        while self._match(TokenKind.COMMA):
            types.append(self._parse_type())
        return types


def parse(source: str, context: Optional[MLIRContext] = None) -> Operation:
    """Parse MLIR source text and return the top-level operation."""
    parser = Parser(source, context)
    return parser.parse_module()


def parse_file(path: str, context: Optional[MLIRContext] = None) -> Operation:
    """Parse an MLIR source file and return the top-level operation."""
    with open(path) as handle:
        return parse(handle.read(), context)

