"""Comb dialect: two-state combinational logic.

Every operation here is a pure function of its operands, so each one supports
both :meth:`CombOp.evaluate` (simulation against a signal environment) and
:meth:`CombOp.fold` (compile-time constant folding, the hardware counterpart of
``mlir.dialects.arith``'s folders).
"""
from __future__ import annotations
from dataclasses import dataclass, field
from typing import Callable, Dict, List, Optional


class CombOp:
    """Base class for combinational operations."""
    op_name: str = "comb.unknown"
    width: int = 0
    operands: List[str] = []
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        raise NotImplementedError

    def fold(self, constants: dict) -> Optional[int]:
        """Attempt constant folding; returns ``None`` when not foldable."""
        return None

    def infer_width(self, type_env: dict) -> int:
        """Infer the result width from the operand types."""
        return self.width

    def mask(self) -> int:
        return (1 << self.width) - 1

    def operand_values(self, env: dict) -> List[int]:
        """Masked operand values, in order."""
        mask = self.mask()
        return [env[name] & mask for name in self.operands]


def _binary_fold(op: CombOp, apply: Callable[[int, int], int],
                 constants: Dict[str, int]) -> Optional[int]:
    """Fold a two-operand `op` when both operands are known constants."""
    if not all(name in constants for name in op.operands):
        return None
    mask = (1 << op.width) - 1
    return apply(constants[op.operands[0]], constants[op.operands[1]]) & mask


@dataclass
class AddOp(CombOp):
    """`comb.add`: ``a + b`` truncated to `width` bits."""
    op_name: str = "comb.add"
    operands: List[str] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        a, b = self.operand_values(env)
        return (a + b) & self.mask()

    def fold(self, constants: dict) -> Optional[int]:
        return _binary_fold(self, lambda a, b: a + b, constants)


@dataclass
class SubOp(CombOp):
    """`comb.sub`: ``a - b`` truncated to `width` bits."""
    op_name: str = "comb.sub"
    operands: List[str] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        a, b = self.operand_values(env)
        return (a - b) & self.mask()

    def fold(self, constants: dict) -> Optional[int]:
        return _binary_fold(self, lambda a, b: a - b, constants)


@dataclass
class MulOp(CombOp):
    """`comb.mul`: ``a * b`` truncated to `width` bits."""
    op_name: str = "comb.mul"
    operands: List[str] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        a, b = self.operand_values(env)
        return (a * b) & self.mask()

    def fold(self, constants: dict) -> Optional[int]:
        return _binary_fold(self, lambda a, b: a * b, constants)


@dataclass
class DivUOp(CombOp):
    """`comb.divu`: unsigned division, ``x / 0`` saturates to all ones."""
    op_name: str = "comb.divu"
    operands: List[str] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        a, b = self.operand_values(env)
        if b == 0:
            return self.mask()
        return (a // b) & self.mask()

    def fold(self, constants: dict) -> Optional[int]:
        if not all(name in constants for name in self.operands):
            return None
        divisor = constants[self.operands[1]]
        if divisor == 0:
            return self.mask()
        return (constants[self.operands[0]] // divisor) & self.mask()


@dataclass
class ModUOp(CombOp):
    """`comb.modu`: unsigned remainder, ``x % 0`` yields ``x``."""
    op_name: str = "comb.modu"
    operands: List[str] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        a, b = self.operand_values(env)
        if b == 0:
            return a
        return (a % b) & self.mask()


@dataclass
class AndOp(CombOp):
    """`comb.and`: bitwise AND."""
    op_name: str = "comb.and"
    operands: List[str] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        a, b = self.operand_values(env)
        return (a & b) & self.mask()

    def fold(self, constants: dict) -> Optional[int]:
        return _binary_fold(self, lambda a, b: a & b, constants)


@dataclass
class OrOp(CombOp):
    """`comb.or`: bitwise OR."""
    op_name: str = "comb.or"
    operands: List[str] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        a, b = self.operand_values(env)
        return (a | b) & self.mask()

    def fold(self, constants: dict) -> Optional[int]:
        return _binary_fold(self, lambda a, b: a | b, constants)


@dataclass
class XorOp(CombOp):
    """`comb.xor`: bitwise XOR."""
    op_name: str = "comb.xor"
    operands: List[str] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        a, b = self.operand_values(env)
        return (a ^ b) & self.mask()

    def fold(self, constants: dict) -> Optional[int]:
        return _binary_fold(self, lambda a, b: a ^ b, constants)


@dataclass
class ShrUOp(CombOp):
    """`comb.shru`: logical (unsigned) shift right."""
    op_name: str = "comb.shru"
    operands: List[str] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        a, b = self.operand_values(env)
        return (a >> b) & self.mask()

    def fold(self, constants: dict) -> Optional[int]:
        return _binary_fold(self, lambda a, b: a >> b, constants)


@dataclass
class ShlOp(CombOp):
    """`comb.shl`: shift left, overflow bits dropped."""
    op_name: str = "comb.shl"
    operands: List[str] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        a, b = self.operand_values(env)
        return (a << b) & self.mask()

    def fold(self, constants: dict) -> Optional[int]:
        return _binary_fold(self, lambda a, b: a << b, constants)


#: Predicates understood by ``comb.icmp``, keyed by mnemonic.
ICMP_PREDICATES: Dict[str, Callable[[int, int], bool]] = {
    "eq": lambda a, b: a == b,
    "ne": lambda a, b: a != b,
    "sgt": lambda a, b: a > b,
    "sge": lambda a, b: a >= b,
    "slt": lambda a, b: a < b,
    "sle": lambda a, b: a <= b,
    "ugt": lambda a, b: a > b,
    "uge": lambda a, b: a >= b,
    "ult": lambda a, b: a < b,
    "ule": lambda a, b: a <= b,
}


@dataclass
class ICmpOp(CombOp):
    """`comb.icmp`: integer comparison producing an ``i1``.

    `width` is the *operand* width used for masking; the result is one bit,
    which is what :meth:`infer_width` reports.
    """
    op_name: str = "comb.icmp"
    predicate: str = "eq"
    operands: List[str] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        a, b = self.operand_values(env)
        compare = ICMP_PREDICATES.get(self.predicate)
        if compare is None:
            return 0
        return 1 if compare(a, b) else 0

    def fold(self, constants: dict) -> Optional[int]:
        if not all(name in constants for name in self.operands):
            return None
        compare = ICMP_PREDICATES.get(self.predicate)
        if compare is None:
            return None
        mask = self.mask()
        lhs = constants[self.operands[0]] & mask
        rhs = constants[self.operands[1]] & mask
        return 1 if compare(lhs, rhs) else 0

    def infer_width(self, type_env: dict) -> int:
        return 1


@dataclass
class MuxOp(CombOp):
    """`comb.mux`: ``cond ? true_value : false_value``."""
    op_name: str = "comb.mux"
    operands: List[str] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        cond = env[self.operands[0]]
        true_val = env[self.operands[1]]
        false_val = env[self.operands[2]]
        return (true_val if cond else false_val) & self.mask()

    def fold(self, constants: dict) -> Optional[int]:
        cond_name = self.operands[0] if self.operands else None
        if cond_name is None or cond_name not in constants:
            return None
        chosen = self.operands[1] if constants[cond_name] else self.operands[2]
        if chosen not in constants:
            return None
        return constants[chosen] & self.mask()


@dataclass
class ConcatOp(CombOp):
    """`comb.concat`: bit concatenation, first operand most significant."""
    op_name: str = "comb.concat"
    operands: List[str] = field(default_factory=list)
    operand_widths: List[int] = field(default_factory=list)
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        result = 0
        shift = 0
        for i in range(len(self.operands) - 1, -1, -1):
            val = env[self.operands[i]] & ((1 << self.operand_widths[i]) - 1)
            result |= val << shift
            shift += self.operand_widths[i]
        return result & ((1 << self.width) - 1)

    def infer_width(self, type_env: dict) -> int:
        return sum(self.operand_widths)


@dataclass
class ExtractOp(CombOp):
    """`comb.extract`: ``input[low_bit + width - 1 : low_bit]``."""
    op_name: str = "comb.extract"
    operands: List[str] = field(default_factory=list)
    low_bit: int = 0
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        val = env[self.operands[0]]
        return (val >> self.low_bit) & self.mask()

    def fold(self, constants: dict) -> Optional[int]:
        if not self.operands or self.operands[0] not in constants:
            return None
        return (constants[self.operands[0]] >> self.low_bit) & self.mask()


@dataclass
class ReplicateOp(CombOp):
    """`comb.replicate`: tile an operand `count` times."""
    op_name: str = "comb.replicate"
    operands: List[str] = field(default_factory=list)
    input_width: int = 0
    count: int = 1
    width: int = 0
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        val = env[self.operands[0]] & ((1 << self.input_width) - 1)
        result = 0
        for i in range(self.count):
            result |= val << (i * self.input_width)
        return result & ((1 << self.width) - 1)

    def infer_width(self, type_env: dict) -> int:
        return self.input_width * self.count


@dataclass
class ParityOp(CombOp):
    """`comb.parity`: XOR reduction of all bits of the operand."""
    op_name: str = "comb.parity"
    operands: List[str] = field(default_factory=list)
    input_width: int = 0
    width: int = 1
    result_name: str = ""

    def evaluate(self, env: dict) -> int:
        val = env[self.operands[0]] & ((1 << self.input_width) - 1)
        parity = 0
        while val:
            parity ^= val & 1
            val >>= 1
        return parity

    def infer_width(self, type_env: dict) -> int:
        return 1


#: Operation classes keyed by their textual mnemonic, used by the parser.
COMB_OPS: Dict[str, type] = {
    "comb.add": AddOp,
    "comb.sub": SubOp,
    "comb.mul": MulOp,
    "comb.divu": DivUOp,
    "comb.modu": ModUOp,
    "comb.and": AndOp,
    "comb.or": OrOp,
    "comb.xor": XorOp,
    "comb.shru": ShrUOp,
    "comb.shl": ShlOp,
    "comb.icmp": ICmpOp,
    "comb.mux": MuxOp,
    "comb.concat": ConcatOp,
    "comb.extract": ExtractOp,
    "comb.replicate": ReplicateOp,
    "comb.parity": ParityOp,
}

