"""Seq dialect: clocked state elements.

These are the only operations in the hardware layer that carry state across a
clock edge, so the cycle-accurate simulator drives them explicitly: it settles
the combinational cone first, then calls :meth:`CompRegOp.tick` (and friends)
once per edge.
"""
from __future__ import annotations
from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Dict, List, Optional


class ResetType(Enum):
    """When a register observes its reset input."""
    SYNC = "synchronous"
    ASYNC = "asynchronous"
    NONE = "none"


@dataclass
class ClockType:
    """`!seq.clock`: the dedicated one-bit clock type."""

    def bit_count(self) -> int:
        return 1

    def __repr__(self) -> str:
        return "!seq.clock"


@dataclass
class ClockDomain:
    """A clock domain with a frequency and an active edge."""
    name: str
    frequency_hz: float = 100e6
    rising_edge: bool = True
    period_ns: float = 0.0

    def __post_init__(self) -> None:
        if self.frequency_hz > 0:
            self.period_ns = 1e9 / self.frequency_hz

    def half_period_ns(self) -> float:
        return self.period_ns / 2.0

    def is_compatible(self, other: ClockDomain) -> bool:
        return self.name == other.name


@dataclass
class CompRegOp:
    """`seq.compreg`: register that samples `input_signal` on each clock edge.

    `reset_value_signal` records the textual name of the reset operand when the
    design writes ``reset %rst, %c0`` and the constant behind ``%c0`` cannot be
    resolved at parse time; the simulator resolves it from the environment.
    """
    name: str
    width: int
    input_signal: str
    clock: str = "clk"
    reset: Optional[str] = None
    reset_value: int = 0
    reset_type: ResetType = ResetType.SYNC
    current_value: int = 0
    clock_domain: Optional[ClockDomain] = None
    reset_value_signal: Optional[str] = None

    def mask(self) -> int:
        return (1 << self.width) - 1

    def next_value(self, env: Dict[str, int]) -> int:
        """The value this register would latch on the next edge."""
        if self.reset and env.get(self.reset, 0):
            return self.reset_value_from(env)
        return env.get(self.input_signal, 0) & self.mask()

    def reset_value_from(self, env: Dict[str, int]) -> int:
        """Reset value, preferring the environment when it is a signal."""
        if self.reset_value_signal and self.reset_value_signal in env:
            return env[self.reset_value_signal] & self.mask()
        return self.reset_value & self.mask()

    def tick(self, env: Dict[str, int]) -> int:
        self.current_value = self.next_value(env)
        return self.current_value

    def async_reset(self, env: Dict[str, int]) -> bool:
        if self.reset_type == ResetType.ASYNC and self.reset:
            if env.get(self.reset, 0):
                self.current_value = self.reset_value_from(env)
                return True
        return False

    def get_value(self) -> int:
        return self.current_value & self.mask()

    def set_value(self, value: int) -> None:
        self.current_value = value & self.mask()


@dataclass
class CompRegClockEnabledOp:
    """`seq.compreg.ce`: register that only samples while its enable is high."""
    name: str
    width: int
    input_signal: str
    clock: str = "clk"
    clock_enable: str = "ce"
    reset: Optional[str] = None
    reset_value: int = 0
    reset_type: ResetType = ResetType.SYNC
    current_value: int = 0

    def tick(self, env: Dict[str, int]) -> int:
        mask = (1 << self.width) - 1
        if self.reset and env.get(self.reset, 0):
            self.current_value = self.reset_value & mask
        elif env.get(self.clock_enable, 0):
            self.current_value = env.get(self.input_signal, 0) & mask
        return self.current_value

    def is_enabled(self, env: Dict[str, int]) -> bool:
        return bool(env.get(self.clock_enable, 0))

    def get_value(self) -> int:
        return self.current_value & ((1 << self.width) - 1)


@dataclass
class FIFOOp:
    """`seq.fifo`: circular buffer of `depth` entries."""
    name: str
    width: int
    depth: int
    clock: str = "clk"
    reset: Optional[str] = None
    buffer: List[int] = field(default_factory=list)
    read_ptr: int = 0
    write_ptr: int = 0
    count: int = 0

    def push(self, value: int) -> bool:
        if self.count >= self.depth:
            return False
        mask = (1 << self.width) - 1
        if len(self.buffer) < self.depth:
            self.buffer.append(value & mask)
        else:
            self.buffer[self.write_ptr] = value & mask
        self.write_ptr = (self.write_ptr + 1) % self.depth
        self.count += 1
        return True

    def pop(self) -> Optional[int]:
        if self.count == 0:
            return None
        value = self.buffer[self.read_ptr]
        self.read_ptr = (self.read_ptr + 1) % self.depth
        self.count -= 1
        return value

    def is_full(self) -> bool:
        return self.count >= self.depth

    def is_empty(self) -> bool:
        return self.count == 0

    def occupancy(self) -> int:
        return self.count


@dataclass
class ShiftRegOp:
    """`seq.shiftreg`: `length`-deep shift register."""
    name: str
    width: int
    length: int
    clock: str = "clk"
    stages: List[int] = field(default_factory=list)

    def __post_init__(self) -> None:
        if not self.stages:
            self.stages = [0] * self.length

    def shift_in(self, value: int) -> int:
        mask = (1 << self.width) - 1
        output = self.stages[-1] if self.stages else 0
        self.stages = [value & mask] + self.stages[:-1]
        return output & mask

    def peek(self, stage: int) -> int:
        if 0 <= stage < self.length:
            return self.stages[stage]
        return 0

    def reset_all(self) -> None:
        self.stages = [0] * self.length


@dataclass
class ClockGateOp:
    """`seq.clock_gate`: gates a clock with an enable (plus test enable)."""
    name: str
    clock_in: str = "clk"
    enable: str = "en"
    test_enable: str = ""
    is_active: bool = False

    def evaluate(self, env: Dict[str, int]) -> bool:
        en = bool(env.get(self.enable, 0))
        te = bool(env.get(self.test_enable, 0)) if self.test_enable else False
        self.is_active = en or te
        return self.is_active

    def clock_output(self, clock_value: int, env: Dict[str, int]) -> int:
        if self.evaluate(env):
            return clock_value
        return 0


@dataclass
class FirRegOp:
    """`seq.firreg`: FIRRTL-flavoured register with an optional preset."""
    name: str
    width: int
    clock: str = "clk"
    reset: Optional[str] = None
    reset_value: int = 0
    preset_value: Optional[int] = None
    current_value: int = 0

    def tick(self, env: Dict[str, int], next_value: int) -> int:
        mask = (1 << self.width) - 1
        if self.reset and env.get(self.reset, 0):
            self.current_value = self.reset_value & mask
        else:
            self.current_value = next_value & mask
        return self.current_value

    def preset(self) -> None:
        if self.preset_value is not None:
            self.current_value = self.preset_value & ((1 << self.width) - 1)

    def get_value(self) -> int:
        return self.current_value & ((1 << self.width) - 1)


#: Register-like operations the simulator has to clock every cycle.
STATEFUL_OPS = (CompRegOp, CompRegClockEnabledOp, FirRegOp)


def is_stateful(op: Any) -> bool:
    """True when `op` holds state across a clock edge."""
    return isinstance(op, STATEFUL_OPS)

