    name: str
    clock_in: str = "clk"
    enable: str = "en"
    test_enable: str = ""
    is_active: bool = False

    def evaluate(self, env: Dict[str, int]) -> bool:
        en = bool(env.get(self.enable, 0))
        te = bool(env.get(self.test_enable, 0)) if self.test_enable else False
        self.is_active = en or te
        return self.is_active

    def clock_output(self, clock_value: int, env: Dict[str, int]) -> int:
        if self.evaluate(env):
            return clock_value
        return 0


@dataclass
class FirRegOp:
    """`seq.firreg`: FIRRTL-flavoured register with an optional preset."""
    name: str
    width: int
    clock: str = "clk"
    reset: Optional[str] = None
    reset_value: int = 0
    preset_value: Optional[int] = None
    current_value: int = 0

    def tick(self, env: Dict[str, int], next_value: int) -> int:
        mask = (1 << self.width) - 1
        if self.reset and env.get(self.reset, 0):
            self.current_value = self.reset_value & mask
        else:
            self.current_value = next_value & mask
        return self.current_value

    def preset(self) -> None:
        if self.preset_value is not None:
            self.current_value = self.preset_value & ((1 << self.width) - 1)

    def get_value(self) -> int:
        return self.current_value & ((1 << self.width) - 1)


#: Register-like operations the simulator has to clock every cycle.
STATEFUL_OPS = (CompRegOp, CompRegClockEnabledOp, FirRegOp)


def is_stateful(op: Any) -> bool:
    """True when `op` holds state across a clock edge."""
    return isinstance(op, STATEFUL_OPS)

