from __future__ import annotations
from dataclasses import dataclass, field
from enum import Enum
from typing import Callable, Dict, List, Optional, Set


class StateEncoding(Enum):
    """How state names are mapped onto register bits."""
    BINARY = "binary"
    ONE_HOT = "one_hot"
    GRAY = "gray"


@dataclass
class TransitionOp:
    """`fsm.transition`: guarded edge to `target_state`."""
    target_state: str
    guard: Optional[Callable[[Dict[str, int]], bool]] = None
    priority: int = 0

    def evaluate_guard(self, env: Dict[str, int]) -> bool:
        if self.guard is None:
            return True
        return self.guard(env)


@dataclass
class FSMOutputOp:
    """`fsm.output`: constant output assignments for a state."""
    assignments: Dict[str, int] = field(default_factory=dict)

    def apply(self, env: Dict[str, int]) -> Dict[str, int]:
        result = dict(env)
        result.update(self.assignments)
        return result


@dataclass
class StateOp:
    """`fsm.state`: one state, its outputs and its outgoing transitions."""
    name: str
    transitions: List[TransitionOp] = field(default_factory=list)
    output: Optional[FSMOutputOp] = None
    is_initial: bool = False

    def add_transition(self, target: str, guard: Optional[Callable] = None,
                       priority: int = 0) -> None:
        self.transitions.append(
            TransitionOp(target_state=target, guard=guard, priority=priority))

    def next_state(self, env: Dict[str, int]) -> Optional[str]:
        """Highest-priority transition whose guard holds, if any."""
        sorted_trans = sorted(self.transitions, key=lambda t: t.priority, reverse=True)
        for trans in sorted_trans:
            if trans.evaluate_guard(env):
                return trans.target_state
        return None

    def get_outputs(self, env: Dict[str, int]) -> Dict[str, int]:
        if self.output is not None:
            return self.output.apply(env)
        return dict(env)


@dataclass
class MachineOp:
    """`fsm.machine`: a machine with states, encoding and static checks."""
    name: str
    states: List[StateOp] = field(default_factory=list)
    encoding: StateEncoding = StateEncoding.BINARY
    current_state: Optional[str] = None
    inputs: List[str] = field(default_factory=list)
    outputs: List[str] = field(default_factory=list)

    def __post_init__(self) -> None:
        if self.current_state is None:
            for state in self.states:
                if state.is_initial:
                    self.current_state = state.name
                    break
            if self.current_state is None and self.states:
                self.current_state = self.states[0].name

    def add_state(self, state: StateOp) -> None:
        self.states.append(state)
        if state.is_initial and self.current_state is None:
            self.current_state = state.name

    def get_state(self, name: str) -> Optional[StateOp]:
        for state in self.states:
            if state.name == name:
                return state
        return None

    def step(self, env: Dict[str, int]) -> Dict[str, int]:
        """Emit the current state's outputs, then take a transition."""
        current = self.get_state(self.current_state)
        if current is None:
            return {}
        outputs = current.get_outputs(env)
        next_name = current.next_state(env)
        if next_name is not None:
            self.current_state = next_name
        return outputs

    def run(self, stimulus: List[Dict[str, int]]) -> List[str]:
        """Step once per stimulus entry, returning the visited state names."""
        visited: List[str] = []
        for env in stimulus:
            self.step(env)
            visited.append(self.current_state or "")
        return visited

    def reset(self) -> None:
        self.current_state = self.initial_state()

    def initial_state(self) -> Optional[str]:
        for state in self.states:
            if state.is_initial:
                return state.name
        return self.states[0].name if self.states else None

    def encode_state(self, state_name: str) -> int:
        idx = next((i for i, s in enumerate(self.states) if s.name == state_name), 0)
        if self.encoding == StateEncoding.BINARY:
            return idx
        elif self.encoding == StateEncoding.ONE_HOT:
            return 1 << idx
        elif self.encoding == StateEncoding.GRAY:
            return idx ^ (idx >> 1)
        return idx

    def encoding_width(self) -> int:
        n = len(self.states)
        if self.encoding == StateEncoding.ONE_HOT:
            return n
        bits = 1
        while (1 << bits) < n:
            bits += 1
        return bits

    def reachable_states(self) -> Set[str]:
        """Breadth-first closure of the transition relation from the start."""
        if not self.states:
            return set()
        initial = self.initial_state()
        visited: Set[str] = set()
        queue = [initial]
        while queue:
            current_name = queue.pop(0)
            if current_name in visited:
                continue
            visited.add(current_name)
            state = self.get_state(current_name)
            if state:
                for trans in state.transitions:
                    if trans.target_state not in visited:
                        queue.append(trans.target_state)
        return visited

    def detect_deadlock(self) -> List[str]:
        """States with no outgoing transition."""
        return [state.name for state in self.states if not state.transitions]

    def verify(self) -> List[str]:
        errors: List[str] = []
        reachable = self.reachable_states()
        all_names = {s.name for s in self.states}
        for name in all_names - reachable:
            errors.append(f"Unreachable state: {name}")
        for name in self.detect_deadlock():
            if name in reachable:
                errors.append(f"Deadlock state: {name}")
        target_names: Set[str] = set()
        for state in self.states:
            for trans in state.transitions:
                target_names.add(trans.target_state)
        for name in target_names - all_names:
            errors.append(f"Invalid transition target: {name}")
        return errors

