            n = sig.get("name", "sig")
            if w == 1:
                lines.append(f"  logic {n};")
            else:
                lines.append(f"  logic [{w - 1}:0] {n};")
        for mp_name, mp_signals in self.modports.items():
            lines.append(f"  modport {mp_name}({', '.join(mp_signals)});")
        lines.append("endinterface")
        return "\n".join(lines)


@dataclass
class GenerateOp:
    """`sv.generate` loop for parameterised instantiation."""
    variable: str = "i"
    start: int = 0
    end: int = 1
    body_template: str = ""

    def emit(self) -> str:
        lines = [f"  genvar {self.variable};"]
        lines.append("  generate")
        lines.append(
            f"    for ({self.variable} = {self.start}; {self.variable} < {self.end}; "
            f"{self.variable} = {self.variable} + 1) begin"
        )
        lines.append(f"      {self.body_template}")
        lines.append("    end")
        lines.append("  endgenerate")
        return "\n".join(lines)


@dataclass
class SVModuleOp:
    """A SystemVerilog module, emitted verbatim from its body operations."""
    name: str
    ports: List[Dict[str, Any]] = field(default_factory=list)
    body: List[Any] = field(default_factory=list)

    def emit(self) -> str:
        port_strs: List[str] = []
        for port in self.ports:
            direction = port.get("direction", "input")
            width = port.get("width", 1)
            pname = port.get("name", "sig")
            if width == 1:
                port_strs.append(f"  {direction} {pname}")
            else:
                port_strs.append(f"  {direction} [{width - 1}:0] {pname}")
        lines = [f"module {self.name} ("]
        lines.append(",\n".join(port_strs))
        lines.append(");")
        for op in self.body:
            if hasattr(op, "emit"):
                lines.append(op.emit())
        lines.append("endmodule")
        return "\n".join(lines)

    def line_count(self) -> int:
        return len(self.emit().split("\n"))

