"""Parser for the CIRCT textual format (`hw` / `comb` / `seq` operations).

This is a thin dialect-specific front end layered on top of the core MLIR
infrastructure: it reuses :class:`mlir.parser.Lexer`, :class:`mlir.parser.Token`
and :class:`mlir.parser.ParseError`, and it can mirror what it parses into
:class:`mlir.ir.Operation` trees via :func:`to_mlir_module`, so the hardware
layer stays connected to the compiler layer rather than duplicating it.

The grammar covered is exactly what ``inputs/alu.mlir`` and
``inputs/counter.mlir`` use, plus the neighbouring spellings that are cheap to
support::

    hw.module @Name(in %a: i4, out result: i4) {
      %r = comb.add %a, %a : i4
      %c = hw.constant 1 : i4
      %p = comb.icmp eq %a, %c : i4
      %m = comb.mux %p, %r, %c : i4
      %q = seq.compreg %m, %clk reset %rst, %c : i4
      hw.output %m : i4
    }
"""
from __future__ import annotations
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

from mlir.ir import (
    IntegerAttr, IntegerType, OpaqueType, Operation, Region, StringAttr, Type,
    Value,
)
from mlir.parser import Lexer, ParseError, Token, TokenKind

from .comb_dialect import (
    COMB_OPS, CombOp, ConcatOp, ExtractOp, ICmpOp, ReplicateOp,
)
from .hw_dialect import (
    ConstantOp, Direction, HWModuleOp, InstanceOp, IntType, OutputOp, Port,
    WireOp,
)
from .seq_dialect import (
    ClockType, CompRegClockEnabledOp, CompRegOp, FirRegOp, ResetType,
)


@dataclass
class Circuit:
    """A parsed design: the `hw.module` definitions found in one source file."""
    name: str = ""
    modules: List[HWModuleOp] = field(default_factory=list)
    source: str = ""

    def add_module(self, module: HWModuleOp) -> None:
        self.modules.append(module)

    def get_module(self, name: str) -> Optional[HWModuleOp]:
        for module in self.modules:
            if module.name == name:
                return module
        return None

    def module_names(self) -> List[str]:
        return [module.name for module in self.modules]

    def top_module(self) -> Optional[HWModuleOp]:
        """The first module, which is the design under test for our inputs."""
        return self.modules[0] if self.modules else None

    def __len__(self) -> int:
        return len(self.modules)

    def __iter__(self):
        return iter(self.modules)


class CIRCTParser:
    """Recursive-descent parser for `hw.module` definitions."""

    def __init__(self, source: str) -> None:
        self._source = source
        self._tokens: List[Token] = Lexer(source).tokens
        self._pos = 0
        #: Bit width of every signal seen so far, keyed by SSA name.
        self.signal_widths: Dict[str, int] = {}
        #: Constant values discovered while parsing, used to fold reset values.
        self.constants: Dict[str, int] = {}

    # -- token helpers ---------------------------------------------------

    def _current(self) -> Token:
        return self._tokens[self._pos]

    def _peek(self, offset: int = 1) -> Token:
        index = min(self._pos + offset, len(self._tokens) - 1)
        return self._tokens[index]

    def _advance(self) -> Token:
        tok = self._tokens[self._pos]
        if tok.kind != TokenKind.EOF:
            self._pos += 1
        return tok

    def _expect(self, kind: TokenKind) -> Token:
        tok = self._current()
        if tok.kind != kind:
            raise ParseError(f"Expected {kind}, got {tok.kind} ({tok.value!r})",
                             tok.line, tok.col)
        return self._advance()

    def _match(self, kind: TokenKind) -> Optional[Token]:
        if self._current().kind == kind:
            return self._advance()
        return None

    def _match_keyword(self, *values: str) -> Optional[Token]:
        tok = self._current()
        if tok.kind in (TokenKind.BARE_IDENTIFIER, TokenKind.KEYWORD) and tok.value in values:
            return self._advance()
        return None

    def _at_end(self) -> bool:
        return self._current().kind == TokenKind.EOF

    def _parse_ssa_name(self) -> str:
        self._expect(TokenKind.PERCENT)
        return self._advance().value

    # -- entry points ----------------------------------------------------

    def parse_circuit(self, name: str = "") -> Circuit:
        """Parse every `hw.module` in the source into a :class:`Circuit`."""
        circuit = Circuit(name=name, source=self._source)
        while not self._at_end():
            if self._current().value in ("hw.module", "hw.module.extern"):
                circuit.add_module(self.parse_module())
            else:
                self._advance()
        if not circuit.name and circuit.modules:
            circuit.name = circuit.modules[0].name
        return circuit

    def parse_module(self) -> HWModuleOp:
        """Parse a single ``hw.module @Name(ports) { body }``."""
        keyword = self._advance().value
        if keyword not in ("hw.module", "hw.module.extern"):
            tok = self._current()
            raise ParseError(f"Expected hw.module, got {keyword!r}", tok.line, tok.col)
        self._expect(TokenKind.AT)
        name = self._advance().value
        ports = self._parse_port_list()
        module = HWModuleOp(name=name, ports=ports)
        for port in ports:
            self.signal_widths[port.name] = port.bit_width()
        if self._current().kind == TokenKind.LBRACE:
            module.body.extend(self._parse_body())
        module.attributes["signal_widths"] = dict(self.signal_widths)
        module.attributes["constants"] = dict(self.constants)
        return module

    # -- ports -----------------------------------------------------------

    def _parse_port_list(self) -> List[Port]:
        ports: List[Port] = []
        if not self._match(TokenKind.LPAREN):
            return ports
        while self._current().kind != TokenKind.RPAREN and not self._at_end():
            ports.append(self._parse_port())
            self._match(TokenKind.COMMA)
        self._expect(TokenKind.RPAREN)
        return ports

    def _parse_port(self) -> Port:
        """``in %a: i4`` / ``out result: i4`` / a bare ``%a: i4`` input."""
        direction = Direction.INPUT
        if self._match_keyword("in"):
            direction = Direction.INPUT
        elif self._match_keyword("out"):
            direction = Direction.OUTPUT
        elif self._match_keyword("inout"):
            direction = Direction.INOUT
        self._match(TokenKind.PERCENT)
        name = self._advance().value
        self._expect(TokenKind.COLON)
        port_type = self._parse_type()
        return Port(name=name, port_type=port_type, direction=direction)

    # -- types -----------------------------------------------------------

    def _parse_type(self) -> Any:
        tok = self._current()
        if tok.kind == TokenKind.EXCLAIM:
            self._advance()
            name = self._advance().value
            if name == "seq.clock":
                return ClockType()
            dialect, _, mnemonic = name.partition(".")
            return OpaqueType(dialect, mnemonic)
        value = self._advance().value
        if value.startswith("i") and value[1:].isdigit():
            return IntType(int(value[1:]))
        return IntType(1)

    def _type_width(self, type_obj: Any) -> int:
        if hasattr(type_obj, "bit_count"):
            return type_obj.bit_count()
        return 1

    def _parse_trailing_types(self) -> List[Any]:
        """Parse ``: t1, t2`` or ``: (t1, t2) -> t3`` after an operation."""
        types: List[Any] = []
        if not self._match(TokenKind.COLON):
            return types
        if self._match(TokenKind.LPAREN):
            while self._current().kind != TokenKind.RPAREN and not self._at_end():
                types.append(self._parse_type())
                self._match(TokenKind.COMMA)
            self._expect(TokenKind.RPAREN)
            if self._match(TokenKind.ARROW):
                self._match(TokenKind.LPAREN)
                result_types: List[Any] = []
                while (self._current().kind not in (TokenKind.RPAREN, TokenKind.EOF)
                       and self._starts_type()):
                    result_types.append(self._parse_type())
                    self._match(TokenKind.COMMA)
                self._match(TokenKind.RPAREN)
                return result_types or types
            return types
        while self._starts_type():
            types.append(self._parse_type())
            if not self._match(TokenKind.COMMA):
                break
        return types

    def _starts_type(self) -> bool:
        tok = self._current()
        if tok.kind == TokenKind.EXCLAIM:
            return True
        if tok.kind not in (TokenKind.BARE_IDENTIFIER, TokenKind.KEYWORD):
            return False
        return tok.value[:1] == "i" and tok.value[1:].isdigit()

    # -- module body -----------------------------------------------------

    def _parse_body(self) -> List[Any]:
        self._expect(TokenKind.LBRACE)
        body: List[Any] = []
        while self._current().kind != TokenKind.RBRACE and not self._at_end():
            op = self._parse_body_operation()
            if op is not None:
                body.append(op)
        self._expect(TokenKind.RBRACE)
        return body

    def _parse_body_operation(self) -> Optional[Any]:
        line = self._current().line
        results: List[str] = []
        if self._current().kind == TokenKind.PERCENT:
            while self._current().kind == TokenKind.PERCENT:
                results.append(self._parse_ssa_name())
                if not self._match(TokenKind.COMMA):
                    break
            self._expect(TokenKind.EQUAL)
        op_name = self._advance().value
        result_name = results[0] if results else ""
        handler = self._HANDLERS.get(op_name)
        if handler is None:
            if op_name in COMB_OPS:
                return self._parse_comb(op_name, result_name)
            self._skip_operation(line)
            return None
        return handler(self, op_name, result_name)

    def _skip_operation(self, line: int) -> None:
        """Drop the remainder of an operation we do not model."""
        while not self._at_end() and self._current().kind != TokenKind.RBRACE:
            if self._current().line != line:
                break
            self._advance()

    def _parse_operand_names(self) -> List[str]:
        names: List[str] = []
        while self._current().kind == TokenKind.PERCENT:
            names.append(self._parse_ssa_name())
            if not self._match(TokenKind.COMMA):
                break
        return names

    def _record(self, name: str, width: int) -> None:
        if name:
            self.signal_widths[name] = width

    # -- individual operations -------------------------------------------

    def _parse_constant(self, op_name: str, result_name: str) -> ConstantOp:
        tok = self._expect(TokenKind.INTEGER_LITERAL)
        types = self._parse_trailing_types()
        width = self._type_width(types[0]) if types else 32
        op = ConstantOp(value=int(tok.value), width=width, result_name=result_name)
        self._record(result_name, width)
        if result_name:
            self.constants[result_name] = op.evaluate()
        return op

    def _parse_comb(self, op_name: str, result_name: str) -> CombOp:
        op_class = COMB_OPS[op_name]
        predicate = ""
        if op_class is ICmpOp:
            tok = self._current()
            if tok.kind in (TokenKind.BARE_IDENTIFIER, TokenKind.KEYWORD):
                predicate = self._advance().value
        operands = self._parse_operand_names()
        low_bit = 0
        if op_class is ExtractOp and self._match_keyword("from"):
            low_bit = int(self._expect(TokenKind.INTEGER_LITERAL).value)
        types = self._parse_trailing_types()
        widths = [self._type_width(t) for t in types]
        width = widths[-1] if widths else self._operand_width(operands)
        if op_class is ICmpOp:
            op = ICmpOp(predicate=predicate or "eq", operands=operands,
                        width=widths[0] if widths else self._operand_width(operands),
                        result_name=result_name)
            self._record(result_name, 1)
            return op
        if op_class is ConcatOp:
            operand_widths = ([self._operand_width([name]) for name in operands]
                              if len(widths) <= 1 else widths)
            total = sum(operand_widths)
            op = ConcatOp(operands=operands, operand_widths=operand_widths,
                          width=total, result_name=result_name)
            self._record(result_name, total)
            return op
        if op_class is ExtractOp:
            op = ExtractOp(operands=operands, low_bit=low_bit, width=width,
                           result_name=result_name)
            self._record(result_name, width)
            return op
        if op_class is ReplicateOp:
            input_width = self._operand_width(operands)
            count = width // input_width if input_width else 1
            op = ReplicateOp(operands=operands, input_width=input_width,
                             count=count, width=width, result_name=result_name)
            self._record(result_name, width)
            return op
        op = op_class(operands=operands, width=width, result_name=result_name)
        self._record(result_name, op.infer_width(self.signal_widths))
        return op

    def _operand_width(self, operands: List[str]) -> int:
        for name in operands:
            if name in self.signal_widths:
                return self.signal_widths[name]
        return 32

    def _parse_compreg(self, op_name: str, result_name: str) -> CompRegOp:
        """``seq.compreg %next, %clk [reset %rst, %rstval] : iN``."""
        operands = self._parse_operand_names()
        reset_signal: Optional[str] = None
        reset_value_signal: Optional[str] = None
        clock_enable: Optional[str] = None
        if op_name == "seq.compreg.ce" and len(operands) > 2:
            clock_enable = operands[2]
        if self._match_keyword("reset"):
            reset_operands = self._parse_operand_names()
            if reset_operands:
                reset_signal = reset_operands[0]
            if len(reset_operands) > 1:
                reset_value_signal = reset_operands[1]
        if self._match_keyword("powerOn", "initial"):
            self._parse_operand_names()
        types = self._parse_trailing_types()
        width = self._type_width(types[-1]) if types else self._operand_width(operands)
        input_signal = operands[0] if operands else ""
        clock = operands[1] if len(operands) > 1 else "clk"
        reset_value = self.constants.get(reset_value_signal or "", 0)
        if clock_enable is not None:
            reg: Any = CompRegClockEnabledOp(
                name=result_name or input_signal, width=width,
                input_signal=input_signal, clock=clock, clock_enable=clock_enable,
                reset=reset_signal, reset_value=reset_value,
            )
        else:
            reg = CompRegOp(
                name=result_name or input_signal, width=width,
                input_signal=input_signal, clock=clock, reset=reset_signal,
                reset_value=reset_value, reset_value_signal=reset_value_signal,
            )
        reg.result_name = result_name
        self._record(result_name, width)
        return reg

    def _parse_firreg(self, op_name: str, result_name: str) -> FirRegOp:
        """``seq.firreg %next clock %clk [reset sync %rst, %val] : iN``."""
        operands = self._parse_operand_names()
        clock = "clk"
        if self._match_keyword("clock"):
            clocks = self._parse_operand_names()
            clock = clocks[0] if clocks else "clk"
        reset_signal: Optional[str] = None
        reset_value = 0
        if self._match_keyword("reset"):
            self._match_keyword("sync", "async")
            reset_operands = self._parse_operand_names()
            if reset_operands:
                reset_signal = reset_operands[0]
            if len(reset_operands) > 1:
                reset_value = self.constants.get(reset_operands[1], 0)
        types = self._parse_trailing_types()
        width = self._type_width(types[-1]) if types else 32
        reg = FirRegOp(name=result_name, width=width, clock=clock,
                       reset=reset_signal, reset_value=reset_value)
        reg.result_name = result_name
        reg.input_signal = operands[0] if operands else ""
        self._record(result_name, width)
        return reg

    def _parse_output(self, op_name: str, result_name: str) -> OutputOp:
        operands = self._parse_operand_names()
        self._parse_trailing_types()
        return OutputOp(operands=operands)

    def _parse_wire(self, op_name: str, result_name: str) -> WireOp:
        operands = self._parse_operand_names()
        types = self._parse_trailing_types()
        width = self._type_width(types[0]) if types else self._operand_width(operands)
        wire = WireOp(name=result_name, wire_type=IntType(width),
                      result_name=result_name)
        wire.input_signal = operands[0] if operands else ""
        self._record(result_name, width)
        return wire

    def _parse_instance(self, op_name: str, result_name: str) -> InstanceOp:
        """``hw.instance "u0" @Sub(a: %x: i4) -> (y: i4)``."""
        instance_name = result_name
        if self._current().kind == TokenKind.STRING_LITERAL:
            instance_name = self._advance().value
        self._expect(TokenKind.AT)
        module_name = self._advance().value
        inputs: Dict[str, Any] = {}
        if self._match(TokenKind.LPAREN):
            while self._current().kind != TokenKind.RPAREN and not self._at_end():
                port_name = self._advance().value
                self._match(TokenKind.COLON)
                operands = self._parse_operand_names()
                self._match(TokenKind.COLON)
                if self._starts_type():
                    self._parse_type()
                if operands:
                    inputs[port_name] = operands[0]
                self._match(TokenKind.COMMA)
            self._expect(TokenKind.RPAREN)
        outputs: List[str] = []
        if self._match(TokenKind.ARROW):
            if self._match(TokenKind.LPAREN):
                while self._current().kind != TokenKind.RPAREN and not self._at_end():
                    outputs.append(self._advance().value)
                    self._match(TokenKind.COLON)
                    if self._starts_type():
                        self._parse_type()
                    self._match(TokenKind.COMMA)
                self._expect(TokenKind.RPAREN)
        instance = InstanceOp(instance_name=instance_name, module_name=module_name,
                              inputs=inputs, outputs=outputs)
        instance.result_name = result_name
        return instance

    #: Operation-name dispatch table, consulted before the generic comb path.
    _HANDLERS = {
        "hw.constant": _parse_constant,
        "hw.output": _parse_output,
        "hw.wire": _parse_wire,
        "hw.instance": _parse_instance,
        "seq.compreg": _parse_compreg,
        "seq.compreg.ce": _parse_compreg,
        "seq.firreg": _parse_firreg,
    }


def parse_circuit(source: str, name: str = "") -> Circuit:
    """Parse CIRCT source text into a :class:`Circuit`."""
    return CIRCTParser(source).parse_circuit(name)


def parse_circuit_file(path: str) -> Circuit:
    """Parse a ``.mlir`` file containing `hw.module` definitions."""
    with open(path) as handle:
        return parse_circuit(handle.read())


def parse_hw_module(source: str) -> HWModuleOp:
    """Parse the first `hw.module` in `source`."""
    circuit = parse_circuit(source)
    module = circuit.top_module()
    if module is None:
        raise ParseError("no hw.module found in source")
    return module


def parse_file(path: str) -> HWModuleOp:
    """Parse a file and return its first `hw.module`."""
    with open(path) as handle:
        return parse_hw_module(handle.read())


def _mlir_type(width: int) -> Type:
    return IntegerType(width)


def to_mlir_operation(module: HWModuleOp) -> Operation:
    """Mirror an :class:`HWModuleOp` into a core-MLIR `hw.module` operation.

    The hardware dialects keep their own light-weight op classes for fast
    simulation; this bridge exposes the same design through
    :class:`mlir.ir.Operation` so the MLIR printer, walkers and pass manager
    can be pointed at a hardware design too.
    """
    widths: Dict[str, int] = dict(module.attributes.get("signal_widths", {}))
    region = Region()
    block = region.add_block()
    values: Dict[str, Value] = {}
    for port in module.ports:
        if port.is_input:
            values[port.name] = block.add_argument(_mlir_type(port.bit_width()))
    for op in module.body:
        name = _op_mnemonic(op)
        operand_names = _op_operand_names(op)
        operands = [values[n] for n in operand_names if n in values]
        result_name = getattr(op, "result_name", "")
        result_width = widths.get(result_name, getattr(op, "width", 1))
        result_types = [_mlir_type(result_width)] if result_name else []
        attributes: Dict[str, Any] = {}
        if isinstance(op, ConstantOp):
            attributes["value"] = IntegerAttr(op.value, _mlir_type(op.width))
        if isinstance(op, ICmpOp):
            attributes["predicate"] = StringAttr(op.predicate)
        if result_name:
            attributes["sv.namehint"] = StringAttr(result_name)
        mlir_op = Operation(name, operands=operands, result_types=result_types,
                            attributes=attributes)
        block.add_operation(mlir_op)
        if result_name and mlir_op.results:
            values[result_name] = mlir_op.get_result(0)
    attrs: Dict[str, Any] = {"sym_name": StringAttr(module.name)}
    return Operation("hw.module", attributes=attrs, regions=[region])


def to_mlir_module(circuit: Circuit) -> Operation:
    """Wrap every module of `circuit` in a `builtin.module` operation."""
    region = Region()
    block = region.add_block()
    for module in circuit.modules:
        block.add_operation(to_mlir_operation(module))
    return Operation("builtin.module", regions=[region])


def _op_mnemonic(op: Any) -> str:
    """Textual operation name for a hardware-dialect op object."""
    if hasattr(op, "op_name"):
        return str(op.op_name)
    if isinstance(op, ConstantOp):
        return "hw.constant"
    if isinstance(op, OutputOp):
        return "hw.output"
    if isinstance(op, WireOp):
        return "hw.wire"
    if isinstance(op, InstanceOp):
        return "hw.instance"
    if isinstance(op, CompRegClockEnabledOp):
        return "seq.compreg.ce"
    if isinstance(op, CompRegOp):
        return "seq.compreg"
    if isinstance(op, FirRegOp):
        return "seq.firreg"
    return "hw.unknown"


def _op_operand_names(op: Any) -> List[str]:
    """SSA names read by `op`, in operand order."""
    if isinstance(op, (CompRegOp, CompRegClockEnabledOp, FirRegOp)):
        names = [getattr(op, "input_signal", "")]
        clock = getattr(op, "clock", "")
        if clock:
            names.append(clock)
        if getattr(op, "reset", None):
            names.append(op.reset)
        return [n for n in names if n]
    if isinstance(op, WireOp):
        return [n for n in [getattr(op, "input_signal", "")] if n]
    if isinstance(op, InstanceOp):
        return list(op.inputs.values())
    return list(getattr(op, "operands", []))


#: Reset behaviour assumed for registers parsed without an explicit type.
DEFAULT_RESET_TYPE = ResetType.SYNC

toolUseResult.content:
"""Parser for the CIRCT textual format (`hw` / `comb` / `seq` operations).

This is a thin dialect-specific front end layered on top of the core MLIR
infrastructure: it reuses :class:`mlir.parser.Lexer`, :class:`mlir.parser.Token`
and :class:`mlir.parser.ParseError`, and it can mirror what it parses into
:class:`mlir.ir.Operation` trees via :func:`to_mlir_module`, so the hardware
layer stays connected to the compiler layer rather than duplicating it.

The grammar covered is exactly what ``inputs/alu.mlir`` and
``inputs/counter.mlir`` use, plus the neighbouring spellings that are cheap to
support::

    hw.module @Name(in %a: i4, out result: i4) {
      %r = comb.add %a, %a : i4
      %c = hw.constant 1 : i4
      %p = comb.icmp eq %a, %c : i4
      %m = comb.mux %p, %r, %c : i4
      %q = seq.compreg %m, %clk reset %rst, %c : i4
      hw.output %m : i4
    }
"""
from __future__ import annotations
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

from mlir.ir import (
    IntegerAttr, IntegerType, OpaqueType, Operation, Region, StringAttr, Type,
    Value,
)
from mlir.parser import Lexer, ParseError, Token, TokenKind

from .comb_dialect import (
    COMB_OPS, CombOp, ConcatOp, ExtractOp, ICmpOp, ReplicateOp,
)
from .hw_dialect import (
    ConstantOp, Direction, HWModuleOp, InstanceOp, IntType, OutputOp, Port,
    WireOp,
)
from .seq_dialect import (
    ClockType, CompRegClockEnabledOp, CompRegOp, FirRegOp, ResetType,
)


@dataclass
class Circuit:
    """A parsed design: the `hw.module` definitions found in one source file."""
    name: str = ""
    modules: List[HWModuleOp] = field(default_factory=list)
    source: str = ""

    def add_module(self, module: HWModuleOp) -> None:
        self.modules.append(module)

    def get_module(self, name: str) -> Optional[HWModuleOp]:
        for module in self.modules:
            if module.name == name:
                return module
        return None

    def module_names(self) -> List[str]:
        return [module.name for module in self.modules]

    def top_module(self) -> Optional[HWModuleOp]:
        """The first module, which is the design under test for our inputs."""
        return self.modules[0] if self.modules else None

    def __len__(self) -> int:
        return len(self.modules)

    def __iter__(self):
        return iter(self.modules)


class CIRCTParser:
    """Recursive-descent parser for `hw.module` definitions."""

    def __init__(self, source: str) -> None:
        self._source = source
        self._tokens: List[Token] = Lexer(source).tokens
        self._pos = 0
        #: Bit width of every signal seen so far, keyed by SSA name.
        self.signal_widths: Dict[str, int] = {}
        #: Constant values discovered while parsing, used to fold reset values.
        self.constants: Dict[str, int] = {}

    # -- token helpers ---------------------------------------------------

    def _current(self) -> Token:
        return self._tokens[self._pos]

    def _peek(self, offset: int = 1) -> Token:
        index = min(self._pos + offset, len(self._tokens) - 1)
        return self._tokens[index]

    def _advance(self) -> Token:
        tok = self._tokens[self._pos]
        if tok.kind != TokenKind.EOF:
            self._pos += 1
        return tok

    def _expect(self, kind: TokenKind) -> Token:
        tok = self._current()
        if tok.kind != kind:
            raise ParseError(f"Expected {kind}, got {tok.kind} ({tok.value!r})",
                             tok.line, tok.col)
        return self._advance()

    def _match(self, kind: TokenKind) -> Optional[Token]:
        if self._current().kind == kind:
            return self._advance()
        return None

    def _match_keyword(self, *values: str) -> Optional[Token]:
        tok = self._current()
        if tok.kind in (TokenKind.BARE_IDENTIFIER, TokenKind.KEYWORD) and tok.value in values:
            return self._advance()
        return None

    def _at_end(self) -> bool:
        return self._current().kind == TokenKind.EOF

    def _parse_ssa_name(self) -> str:
        self._expect(TokenKind.PERCENT)
        return self._advance().value

    # -- entry points ----------------------------------------------------

    def parse_circuit(self, name: str = "") -> Circuit:
        """Parse every `hw.module` in the source into a :class:`Circuit`."""
        circuit = Circuit(name=name, source=self._source)
        while not self._at_end():
            if self._current().value in ("hw.module", "hw.module.extern"):
                circuit.add_module(self.parse_module())
            else:
                self._advance()
        if not circuit.name and circuit.modules:
            circuit.name = circuit.modules[0].name
        return circuit

    def parse_module(self) -> HWModuleOp:
        """Parse a single ``hw.module @Name(ports) { body }``."""
        keyword = self._advance().value
        if keyword not in ("hw.module", "hw.module.extern"):
            tok = self._current()
            raise ParseError(f"Expected hw.module, got {keyword!r}", tok.line, tok.col)
        self._expect(TokenKind.AT)
        name = self._advance().value
        ports = self._parse_port_list()
        module = HWModuleOp(name=name, ports=ports)
        for port in ports:
            self.signal_widths[port.name] = port.bit_width()
        if self._current().kind == TokenKind.LBRACE:
            module.body.extend(self._parse_body())
        module.attributes["signal_widths"] = dict(self.signal_widths)
        module.attributes["constants"] = dict(self.constants)
        return module

    # -- ports -----------------------------------------------------------

    def _parse_port_list(self) -> List[Port]:
        ports: List[Port] = []
        if not self._match(TokenKind.LPAREN):
            return ports
        while self._current().kind != TokenKind.RPAREN and not self._at_end():
            ports.append(self._parse_port())
            self._match(TokenKind.COMMA)
        self._expect(TokenKind.RPAREN)
        return ports

    def _parse_port(self) -> Port:
        """``in %a: i4`` / ``out result: i4`` / a bare ``%a: i4`` input."""
        direction = Direction.INPUT
        if self._match_keyword("in"):
            direction = Direction.INPUT
        elif self._match_keyword("out"):
            direction = Direction.OUTPUT
        elif self._match_keyword("inout"):
            direction = Direction.INOUT
        self._match(TokenKind.PERCENT)
        name = self._advance().value
        self._expect(TokenKind.COLON)
        port_type = self._parse_type()
        return Port(name=name, port_type=port_type, direction=direction)

    # -- types -----------------------------------------------------------

    def _parse_type(self) -> Any:
        tok = self._current()
        if tok.kind == TokenKind.EXCLAIM:
            self._advance()
            name = self._advance().value
            if name == "seq.clock":
                return ClockType()
            dialect, _, mnemonic = name.partition(".")
            return OpaqueType(dialect, mnemonic)
        value = self._advance().value
        if value.startswith("i") and value[1:].isdigit():
            return IntType(int(value[1:]))
        return IntType(1)

    def _type_width(self, type_obj: Any) -> int:
        if hasattr(type_obj, "bit_count"):
            return type_obj.bit_count()
        return 1

    def _parse_trailing_types(self) -> List[Any]:
        """Parse ``: t1, t2`` or ``: (t1, t2) -> t3`` after an operation."""
        types: List[Any] = []
        if not self._match(TokenKind.COLON):
            return types
        if self._match(TokenKind.LPAREN):
            while self._current().kind != TokenKind.RPAREN and not self._at_end():
                types.append(self._parse_type())
                self._match(TokenKind.COMMA)
            self._expect(TokenKind.RPAREN)
            if self._match(TokenKind.ARROW):
                self._match(TokenKind.LPAREN)
                result_types: List[Any] = []
                while (self._current().kind not in (TokenKind.RPAREN, TokenKind.EOF)
                       and self._starts_type()):
                    result_types.append(self._parse_type())
                    self._match(TokenKind.COMMA)
                self._match(TokenKind.RPAREN)
                return result_types or types
            return types
        while self._starts_type():
            types.append(self._parse_type())
            if not self._match(TokenKind.COMMA):
                break
        return types

    def _starts_type(self) -> bool:
        tok = self._current()
        if tok.kind == TokenKind.EXCLAIM:
            return True
        if tok.kind not in (TokenKind.BARE_IDENTIFIER, TokenKind.KEYWORD):
            return False
        return tok.value[:1] == "i" and tok.value[1:].isdigit()

    # -- module body -----------------------------------------------------

    def _parse_body(self) -> List[Any]:
        self._expect(TokenKind.LBRACE)
        body: List[Any] = []
        while self._current().kind != TokenKind.RBRACE and not self._at_end():
            op = self._parse_body_operation()
            if op is not None:
                body.append(op)
        self._expect(TokenKind.RBRACE)
        return body

    def _parse_body_operation(self) -> Optional[Any]:
        line = self._current().line
        results: List[str] = []
        if self._current().kind == TokenKind.PERCENT:
            while self._current().kind == TokenKind.PERCENT:
                results.append(self._parse_ssa_name())
                if not self._match(TokenKind.COMMA):
                    break
            self._expect(TokenKind.EQUAL)
        op_name = self._advance().value
        result_name = results[0] if results else ""
        handler = self._HANDLERS.get(op_name)
        if handler is None:
            if op_name in COMB_OPS:
                return self._parse_comb(op_name, result_name)
            self._skip_operation(line)
            return None
        return handler(self, op_name, result_name)

    def _skip_operation(self, line: int) -> None:
        """Drop the remainder of an operation we do not model."""
        while not self._at_end() and self._current().kind != TokenKind.RBRACE:
            if self._current().line != line:
                break
            self._advance()

    def _parse_operand_names(self) -> List[str]:
        names: List[str] = []
        while self._current().kind == TokenKind.PERCENT:
            names.append(self._parse_ssa_name())
            if not self._match(TokenKind.COMMA):
                break
        return names

    def _record(self, name: str, width: int) -> None:
        if name:
            self.signal_widths[name] = width

    # -- individual operations -------------------------------------------

    def _parse_constant(self, op_name: str, result_name: str) -> ConstantOp:
        tok = self._expect(TokenKind.INTEGER_LITERAL)
        types = self._parse_trailing_types()
        width = self._type_width(types[0]) if types else 32
        op = ConstantOp(value=int(tok.value), width=width, result_name=result_name)
        self._record(result_name, width)
        if result_name:
            self.constants[result_name] = op.evaluate()
        return op

    def _parse_comb(self, op_name: str, result_name: str) -> CombOp:
        op_class = COMB_OPS[op_name]
        predicate = ""
        if op_class is ICmpOp:
            tok = self._current()
            if tok.kind in (TokenKind.BARE_IDENTIFIER, TokenKind.KEYWORD):
                predicate = self._advance().value
        operands = self._parse_operand_names()
        low_bit = 0
        if op_class is ExtractOp and self._match_keyword("from"):
            low_bit = int(self._expect(TokenKind.INTEGER_LITERAL).value)
        types = self._parse_trailing_types()
        widths = [self._type_width(t) for t in types]
        width = widths[-1] if widths else self._operand_width(operands)
        if op_class is ICmpOp:
            op = ICmpOp(predicate=predicate or "eq", operands=operands,
                        width=widths[0] if widths else self._operand_width(operands),
                        result_name=result_name)
            self._record(result_name, 1)
            return op
        if op_class is ConcatOp:
            operand_widths = ([self._operand_width([name]) for name in operands]
                              if len(widths) <= 1 else widths)
            total = sum(operand_widths)
            op = ConcatOp(operands=operands, operand_widths=operand_widths,
                          width=total, result_name=result_name)
            self._record(result_name, total)
            return op
        if op_class is ExtractOp:
            op = ExtractOp(operands=operands, low_bit=low_bit, width=width,
                           result_name=result_name)
            self._record(result_name, width)
            return op
        if op_class is ReplicateOp:
            input_width = self._operand_width(operands)
            count = width // input_width if input_width else 1
            op = ReplicateOp(operands=operands, input_width=input_width,
                             count=count, width=width, result_name=result_name)
            self._record(result_name, width)
            return op
        op = op_class(operands=operands, width=width, result_name=result_name)
        self._record(result_name, op.infer_width(self.signal_widths))
        return op

    def _operand_width(self, operands: List[str]) -> int:
        for name in operands:
            if name in self.signal_widths:
                return self.signal_widths[name]
        return 32

    def _parse_compreg(self, op_name: str, result_name: str) -> CompRegOp:
        """``seq.compreg %next, %clk [reset %rst, %rstval] : iN``."""
        operands = self._parse_operand_names()
        reset_signal: Optional[str] = None
        reset_value_signal: Optional[str] = None
        clock_enable: Optional[str] = None
        if op_name == "seq.compreg.ce" and len(operands) > 2:
            clock_enable = operands[2]
        if self._match_keyword("reset"):
            reset_operands = self._parse_operand_names()
            if reset_operands:
                reset_signal = reset_operands[0]
            if len(reset_operands) > 1:
                reset_value_signal = reset_operands[1]
        if self._match_keyword("powerOn", "initial"):
            self._parse_operand_names()
        types = self._parse_trailing_types()
        width = self._type_width(types[-1]) if types else self._operand_width(operands)
        input_signal = operands[0] if operands else ""
        clock = operands[1] if len(operands) > 1 else "clk"
        reset_value = self.constants.get(reset_value_signal or "", 0)
        if clock_enable is not None:
            reg: Any = CompRegClockEnabledOp(
                name=result_name or input_signal, width=width,
                input_signal=input_signal, clock=clock, clock_enable=clock_enable,
                reset=reset_signal, reset_value=reset_value,
            )
        else:
            reg = CompRegOp(
                name=result_name or input_signal, width=width,
                input_signal=input_signal, clock=clock, reset=reset_signal,
                reset_value=reset_value, reset_value_signal=reset_value_signal,
            )
        reg.result_name = result_name
        self._record(result_name, width)
        return reg

    def _parse_firreg(self, op_name: str, result_name: str) -> FirRegOp:
        """``seq.firreg %next clock %clk [reset sync %rst, %val] : iN``."""
        operands = self._parse_operand_names()
        clock = "clk"
        if self._match_keyword("clock"):
            clocks = self._parse_operand_names()
            clock = clocks[0] if clocks else "clk"
        reset_signal: Optional[str] = None
        reset_value = 0
        if self._match_keyword("reset"):
            self._match_keyword("sync", "async")
            reset_operands = self._parse_operand_names()
            if reset_operands:
                reset_signal = reset_operands[0]
            if len(reset_operands) > 1:
                reset_value = self.constants.get(reset_operands[1], 0)
        types = self._parse_trailing_types()
        width = self._type_width(types[-1]) if types else 32
        reg = FirRegOp(name=result_name, width=width, clock=clock,
                       reset=reset_signal, reset_value=reset_value)
        reg.result_name = result_name
        reg.input_signal = operands[0] if operands else ""
        self._record(result_name, width)
        return reg

    def _parse_output(self, op_name: str, result_name: str) -> OutputOp:
        operands = self._parse_operand_names()
        self._parse_trailing_types()
        return OutputOp(operands=operands)

    def _parse_wire(self, op_name: str, result_name: str) -> WireOp:
        operands = self._parse_operand_names()
        types = self._parse_trailing_types()
        width = self._type_width(types[0]) if types else self._operand_width(operands)
        wire = WireOp(name=result_name, wire_type=IntType(width),
                      result_name=result_name)
        wire.input_signal = operands[0] if operands else ""
        self._record(result_name, width)
        return wire

    def _parse_instance(self, op_name: str, result_name: str) -> InstanceOp:
        """``hw.instance "u0" @Sub(a: %x: i4) -> (y: i4)``."""
        instance_name = result_name
        if self._current().kind == TokenKind.STRING_LITERAL:
            instance_name = self._advance().value
        self._expect(TokenKind.AT)
        module_name = self._advance().value
        inputs: Dict[str, Any] = {}
        if self._match(TokenKind.LPAREN):
            while self._current().kind != TokenKind.RPAREN and not self._at_end():
                port_name = self._advance().value
                self._match(TokenKind.COLON)
                operands = self._parse_operand_names()
                self._match(TokenKind.COLON)
                if self._starts_type():
                    self._parse_type()
                if operands:
                    inputs[port_name] = operands[0]
                self._match(TokenKind.COMMA)
            self._expect(TokenKind.RPAREN)
        outputs: List[str] = []
        if self._match(TokenKind.ARROW):
            if self._match(TokenKind.LPAREN):
                while self._current().kind != TokenKind.RPAREN and not self._at_end():
                    outputs.append(self._advance().value)
                    self._match(TokenKind.COLON)
                    if self._starts_type():
                        self._parse_type()
                    self._match(TokenKind.COMMA)
                self._expect(TokenKind.RPAREN)
        instance = InstanceOp(instance_name=instance_name, module_name=module_name,
                              inputs=inputs, outputs=outputs)
        instance.result_name = result_name
        return instance

    #: Operation-name dispatch table, consulted before the generic comb path.
    _HANDLERS = {
        "hw.constant": _parse_constant,
        "hw.output": _parse_output,
        "hw.wire": _parse_wire,
        "hw.instance": _parse_instance,
        "seq.compreg": _parse_compreg,
        "seq.compreg.ce": _parse_compreg,
        "seq.firreg": _parse_firreg,
    }


def parse_circuit(source: str, name: str = "") -> Circuit:
    """Parse CIRCT source text into a :class:`Circuit`."""
    return CIRCTParser(source).parse_circuit(name)


def parse_circuit_file(path: str) -> Circuit:
    """Parse a ``.mlir`` file containing `hw.module` definitions."""
    with open(path) as handle:
        return parse_circuit(handle.read())


def parse_hw_module(source: str) -> HWModuleOp:
    """Parse the first `hw.module` in `source`."""
    circuit = parse_circuit(source)
    module = circuit.top_module()
    if module is None:
        raise ParseError("no hw.module found in source")
    return module


def parse_file(path: str) -> HWModuleOp:
    """Parse a file and return its first `hw.module`."""
    with open(path) as handle:
        return parse_hw_module(handle.read())


def _mlir_type(width: int) -> Type:
    return IntegerType(width)


def to_mlir_operation(module: HWModuleOp) -> Operation:
    """Mirror an :class:`HWModuleOp` into a core-MLIR `hw.module` operation.

    The hardware dialects keep their own light-weight op classes for fast
    simulation; this bridge exposes the same design through
    :class:`mlir.ir.Operation` so the MLIR printer, walkers and pass manager
    can be pointed at a hardware design too.
    """
    widths: Dict[str, int] = dict(module.attributes.get("signal_widths", {}))
    region = Region()
    block = region.add_block()
    values: Dict[str, Value] = {}
    for port in module.ports:
        if port.is_input:
            values[port.name] = block.add_argument(_mlir_type(port.bit_width()))
    for op in module.body:
        name = _op_mnemonic(op)
        operand_names = _op_operand_names(op)
        operands = [values[n] for n in operand_names if n in values]
        result_name = getattr(op, "result_name", "")
        result_width = widths.get(result_name, getattr(op, "width", 1))
        result_types = [_mlir_type(result_width)] if result_name else []
        attributes: Dict[str, Any] = {}
        if isinstance(op, ConstantOp):
            attributes["value"] = IntegerAttr(op.value, _mlir_type(op.width))
        if isinstance(op, ICmpOp):
            attributes["predicate"] = StringAttr(op.predicate)
        if result_name:
            attributes["sv.namehint"] = StringAttr(result_name)
        mlir_op = Operation(name, operands=operands, result_types=result_types,
                            attributes=attributes)
        block.add_operation(mlir_op)
        if result_name and mlir_op.results:
            values[result_name] = mlir_op.get_result(0)
    attrs: Dict[str, Any] = {"sym_name": StringAttr(module.name)}
    return Operation("hw.module", attributes=attrs, regions=[region])


def to_mlir_module(circuit: Circuit) -> Operation:
    """Wrap every module of `circuit` in a `builtin.module` operation."""
    region = Region()
    block = region.add_block()
    for module in circuit.modules:
        block.add_operation(to_mlir_operation(module))
    return Operation("builtin.module", regions=[region])


def _op_mnemonic(op: Any) -> str:
    """Textual operation name for a hardware-dialect op object."""
    if hasattr(op, "op_name"):
        return str(op.op_name)
    if isinstance(op, ConstantOp):
        return "hw.constant"
    if isinstance(op, OutputOp):
        return "hw.output"
    if isinstance(op, WireOp):
        return "hw.wire"
    if isinstance(op, InstanceOp):
        return "hw.instance"
    if isinstance(op, CompRegClockEnabledOp):
        return "seq.compreg.ce"
    if isinstance(op, CompRegOp):
        return "seq.compreg"
    if isinstance(op, FirRegOp):
        return "seq.firreg"
    return "hw.unknown"


def _op_operand_names(op: Any) -> List[str]:
    """SSA names read by `op`, in operand order."""
    if isinstance(op, (CompRegOp, CompRegClockEnabledOp, FirRegOp)):
        names = [getattr(op, "input_signal", "")]
        clock = getattr(op, "clock", "")
        if clock:
            names.append(clock)
        if getattr(op, "reset", None):
            names.append(op.reset)
        return [n for n in names if n]
    if isinstance(op, WireOp):
        return [n for n in [getattr(op, "input_signal", "")] if n]
    if isinstance(op, InstanceOp):
        return list(op.inputs.values())
    return list(getattr(op, "operands", []))


#: Reset behaviour assumed for registers parsed without an explicit type.
DEFAULT_RESET_TYPE = ResetType.SYNC

