"""Cycle-accurate simulator for `hw`/`comb`/`seq` designs.

The evaluation model is the standard two-phase one used by RTL simulators:

1. *settle* -- repeatedly evaluate combinational operations until no signal
   changes. Registers contribute their currently latched value, which is what
   breaks the cycle in a design like ``inputs/counter.mlir`` where
   ``%reg`` and ``%next`` refer to each other.
2. *edge* -- sample every register's next value from the settled environment
   and latch them all at once, so registers update in parallel.

:class:`CircuitSimulator` drives both phases; purely combinational designs such
as ``inputs/alu.mlir`` only need the first one, which
:meth:`CircuitSimulator.evaluate` exposes directly.
"""
from __future__ import annotations
from dataclasses import dataclass, field
from typing import Any, Dict, Iterable, List, Optional

from .comb_dialect import CombOp
from .hw_dialect import (
    ConstantOp, HWModuleOp, InstanceOp, OutputOp, Port, WireOp,
)
from .seq_dialect import CompRegClockEnabledOp, CompRegOp, FirRegOp, is_stateful


class SimulationError(RuntimeError):
    """Raised when a design cannot be evaluated (e.g. a combinational loop)."""


@dataclass
class SignalTrace:
    """Per-cycle history of the signals in a simulated design."""
    signals: List[str] = field(default_factory=list)
    cycles: List[Dict[str, int]] = field(default_factory=list)

    def record(self, env: Dict[str, int]) -> None:
        snapshot = dict(env)
        for name in snapshot:
            if name not in self.signals:
                self.signals.append(name)
        self.cycles.append(snapshot)

    def history(self, signal: str) -> List[int]:
        """Values taken by `signal`, one entry per recorded cycle."""
        return [cycle.get(signal, 0) for cycle in self.cycles]

    def at(self, cycle: int) -> Dict[str, int]:
        return dict(self.cycles[cycle])

    def transitions(self, signal: str) -> int:
        """Number of cycles in which `signal` changed value."""
        values = self.history(signal)
        return sum(1 for a, b in zip(values, values[1:]) if a != b)

    def __len__(self) -> int:
        return len(self.cycles)


class CircuitSimulator:
    """Cycle-accurate interpreter for a single :class:`HWModuleOp`."""

    #: Safety valve for the combinational fixed point.
    MAX_SETTLE_ITERATIONS = 256

    def __init__(self, module: HWModuleOp,
                 circuit: Optional[Any] = None,
                 trace_enabled: bool = True) -> None:
        self.module = module
        self.circuit = circuit
        self.cycle: int = 0
        self.trace = SignalTrace()
        self.trace_enabled = trace_enabled
        self.signal_widths: Dict[str, int] = dict(
            module.attributes.get("signal_widths", {}))
        self.inputs: Dict[str, int] = {p.name: 0 for p in module.input_ports}
        self.signals: Dict[str, int] = {}
        self.registers: Dict[str, Any] = {}
        self.instances: Dict[str, "CircuitSimulator"] = {}
        self._comb_ops: List[Any] = []
        self._constants: List[ConstantOp] = []
        self._collect_operations()
        self.reset()

    # -- setup -----------------------------------------------------------

    def _collect_operations(self) -> None:
        for op in self.module.body:
            if isinstance(op, ConstantOp):
                self._constants.append(op)
            elif is_stateful(op):
                name = getattr(op, "result_name", "") or op.name
                self.registers[name] = op
            elif isinstance(op, InstanceOp):
                self._bind_instance(op)
            elif isinstance(op, (CombOp, WireOp)):
                self._comb_ops.append(op)

    def _bind_instance(self, op: InstanceOp) -> None:
        """Elaborate a submodule instance when its definition is available."""
        if self.circuit is None:
            return
        submodule = self.circuit.get_module(op.module_name)
        if submodule is None:
            return
        self.instances[op.instance_name] = CircuitSimulator(
            submodule, circuit=self.circuit, trace_enabled=False)

    @property
    def output_ports(self) -> List[Port]:
        return self.module.output_ports

    def width_of(self, signal: str) -> int:
        return self.signal_widths.get(signal, 32)

    # -- stimulus --------------------------------------------------------

    def set_input(self, name: str, value: int) -> None:
        """Drive input port `name` with `value` (truncated to its width)."""
        mask = (1 << self.width_of(name)) - 1
        self.inputs[name] = value & mask

    def set_inputs(self, values: Dict[str, int]) -> None:
        for name, value in values.items():
            self.set_input(name, value)

    #: RTL-testbench aliases, matching the vocabulary of hardware simulators.
    poke = set_input

    def get_signal(self, name: str) -> int:
        """Current value of any signal, port or register in the design."""
        if name in self.signals:
            return self.signals[name]
        if name in self.registers:
            return self.registers[name].get_value()
        return self.inputs.get(name, 0)

    peek = get_signal

    def get_output(self, name: Optional[str] = None) -> int:
        """Value of output port `name`, or of the first output port."""
        outputs = self.outputs()
        if name is None:
            return next(iter(outputs.values()), 0)
        return outputs.get(name, 0)

    def outputs(self) -> Dict[str, int]:
        """All output ports mapped to the signals `hw.output` returns."""
        result: Dict[str, int] = {}
        terminator = self.module.terminator
        ports = self.output_ports
        if terminator is None:
            return result
        for index, port in enumerate(ports):
            if index < len(terminator.operands):
                result[port.name] = self.get_signal(terminator.operands[index])
        return result

    # -- evaluation ------------------------------------------------------

    def reset(self, cycles: int = 0) -> None:
        """Clear signal state; optionally hold the reset input for `cycles`."""
        self.cycle = 0
        self.signals = {}
        self.trace = SignalTrace()
        for register in self.registers.values():
            register.current_value = 0
        for instance in self.instances.values():
            instance.reset()
        if cycles:
            reset_port = self._reset_port_name()
            saved = self.inputs.get(reset_port, 0) if reset_port else 0
            if reset_port:
                self.set_input(reset_port, 1)
            for _ in range(cycles):
                self.step()
            if reset_port:
                self.set_input(reset_port, saved)
        else:
            self.evaluate()

    def _reset_port_name(self) -> Optional[str]:
        for register in self.registers.values():
            if getattr(register, "reset", None):
                return register.reset
        for port in self.module.input_ports:
            if port.name in ("reset", "rst", "rst_n"):
                return port.name
        return None

    def _environment(self) -> Dict[str, int]:
        env: Dict[str, int] = dict(self.inputs)
        for name, register in self.registers.items():
            env[name] = register.get_value()
        for const in self._constants:
            if const.result_name:
                env[const.result_name] = const.evaluate()
        return env

    def evaluate(self, inputs: Optional[Dict[str, int]] = None) -> Dict[str, int]:
        """Settle the combinational cone and return the full signal map."""
        if inputs:
            self.set_inputs(inputs)
        env = self._environment()
        pending = list(self._comb_ops)
        iterations = 0
        while pending and iterations < self.MAX_SETTLE_ITERATIONS:
            iterations += 1
            progressed = False
            still_pending: List[Any] = []
            for op in pending:
                value = self._try_evaluate(op, env)
                if value is None:
                    still_pending.append(op)
                    continue
                name = getattr(op, "result_name", "")
                if name:
                    env[name] = value
                progressed = True
            pending = still_pending
            if not progressed:
                break
        if pending:
            unresolved = ", ".join(
                getattr(op, "result_name", "?") for op in pending)
            raise SimulationError(
                f"cannot settle combinational logic in @{self.module.name}: "
                f"unresolved signals {unresolved}")
        self._evaluate_instances(env)
        self.signals = env
        return dict(env)

    def _try_evaluate(self, op: Any, env: Dict[str, int]) -> Optional[int]:
        """Evaluate `op` when all its operands are known, else ``None``."""
        if isinstance(op, WireOp):
            source = getattr(op, "input_signal", "")
            return env.get(source) if source in env else None
        operands: Iterable[str] = getattr(op, "operands", [])
        if any(name not in env for name in operands):
            return None
        return op.evaluate(env)

    def _evaluate_instances(self, env: Dict[str, int]) -> None:
        for name, instance in self.instances.items():
            op = next((o for o in self.module.body
                       if isinstance(o, InstanceOp) and o.instance_name == name), None)
            if op is None:
                continue
            instance.set_inputs({port: env.get(signal, 0)
                                 for port, signal in op.inputs.items()})
            instance.evaluate()
            for index, out_name in enumerate(op.outputs):
                ports = instance.output_ports
                if index < len(ports):
                    env[out_name] = instance.get_output(ports[index].name)

    def step(self, inputs: Optional[Dict[str, int]] = None) -> Dict[str, int]:
        """Advance one clock cycle: settle, latch every register, re-settle."""
        env = self.evaluate(inputs)
        next_values: Dict[str, int] = {}
        for name, register in self.registers.items():
            next_values[name] = self._register_next(register, env)
        for name, register in self.registers.items():
            register.current_value = next_values[name]
        for instance in self.instances.values():
            instance.step()
        self.cycle += 1
        env = self.evaluate()
        if self.trace_enabled:
            self.trace.record(env)
        return env

    tick = step

    def _register_next(self, register: Any, env: Dict[str, int]) -> int:
        if isinstance(register, FirRegOp):
            source = getattr(register, "input_signal", "")
            mask = (1 << register.width) - 1
            if register.reset and env.get(register.reset, 0):
                return register.reset_value & mask
            return env.get(source, 0) & mask
        if isinstance(register, CompRegClockEnabledOp):
            mask = (1 << register.width) - 1
            if register.reset and env.get(register.reset, 0):
                return register.reset_value & mask
            if env.get(register.clock_enable, 0):
                return env.get(register.input_signal, 0) & mask
            return register.get_value()
        return register.next_value(env)

    def run(self, cycles: int,
            inputs: Optional[Dict[str, int]] = None) -> List[Dict[str, int]]:
        """Run `cycles` clock cycles, returning the settled env of each."""
        history: List[Dict[str, int]] = []
        for _ in range(cycles):
            history.append(self.step(inputs))
        return history

    def run_combinational(self, inputs: Dict[str, int]) -> Dict[str, int]:
        """Apply `inputs` to a combinational design and read its outputs."""
        self.evaluate(inputs)
        return self.outputs()

    def register_values(self) -> Dict[str, int]:
        return {name: reg.get_value() for name, reg in self.registers.items()}

    def __repr__(self) -> str:
        return (f"CircuitSimulator(@{self.module.name}, cycle={self.cycle}, "
                f"registers={len(self.registers)})")


#: Shorter alias, matching how testbenches usually spell it.
Simulator = CircuitSimulator


def simulate_module(module: HWModuleOp, inputs: Dict[str, int],
                    cycles: int = 0) -> Dict[str, int]:
    """Convenience wrapper: drive `inputs`, run `cycles`, return the outputs."""
    sim = CircuitSimulator(module)
    sim.set_inputs(inputs)
    if cycles:
        sim.run(cycles)
    else:
        sim.evaluate()
    return sim.outputs()

