"""Printer for hardware designs, reusing the MLIR printer infrastructure.

Two directions are supported:

* :func:`print_hw_module` re-emits the CIRCT surface syntax, so a design parsed
  out of ``inputs/alu.mlir`` round-trips back to equivalent text;
* :class:`HWPrinter` extends :class:`mlir.printer.Printer` so an `hw.module`
  mirrored into core MLIR (see :func:`circt.parser.to_mlir_operation`) prints
  with its symbol name instead of the generic form.
"""
from __future__ import annotations
from typing import Any, Dict, List

from mlir.ir import Operation
from mlir.printer import Printer

from .comb_dialect import CombOp, ConcatOp, ExtractOp, ICmpOp
from .hw_dialect import ConstantOp, HWModuleOp, InstanceOp, OutputOp, WireOp
from .parser import Circuit
from .seq_dialect import CompRegClockEnabledOp, CompRegOp, FirRegOp


class HWPrinter(Printer):
    """MLIR printer that knows the `hw.module` short form."""

    def _print_op(self, op: Operation) -> None:
        if str(op.name) == "hw.module":
            self._print_hw_module(op)
            return
        super()._print_op(op)

    def _print_hw_module(self, op: Operation) -> None:
        indent = self._indent()
        sym = op.get_attr("sym_name")
        name = str(sym).strip('"') if sym is not None else ""
        args: List[str] = []
        if op.regions and op.regions[0].blocks:
            for arg in op.regions[0].blocks[0].arguments:
                args.append(f"in {self._name_state.get_value_name(arg)}: {arg.type}")
        self._output.write(f"{indent}hw.module @{name}({', '.join(args)}) {{\n")
        self._indent_level += 1
        for region in op.regions:
            for block in region.blocks:
                for inner in block.operations:
                    super()._print_op(inner)
        self._indent_level -= 1
        self._output.write(f"{indent}}}\n")


def _type_suffix(width: int) -> str:
    return f"i{width}"


def _op_text(op: Any, widths: Dict[str, int]) -> str:
    """Render one body operation in CIRCT surface syntax."""
    if isinstance(op, ConstantOp):
        return (f"%{op.result_name} = hw.constant {op.value} : "
                f"{_type_suffix(op.width)}")
    if isinstance(op, OutputOp):
        operands = ", ".join(f"%{name}" for name in op.operands)
        types = ", ".join(_type_suffix(widths.get(name, 1)) for name in op.operands)
        if not operands:
            return "hw.output"
        return f"hw.output {operands} : {types}"
    if isinstance(op, (CompRegOp, CompRegClockEnabledOp, FirRegOp)):
        result = getattr(op, "result_name", "") or op.name
        text = f"%{result} = seq.compreg %{op.input_signal}, %{op.clock}"
        if isinstance(op, CompRegClockEnabledOp):
            text = (f"%{result} = seq.compreg.ce %{op.input_signal}, "
                    f"%{op.clock}, %{op.clock_enable}")
        if getattr(op, "reset", None):
            reset_value = getattr(op, "reset_value_signal", None)
            if reset_value:
                text += f" reset %{op.reset}, %{reset_value}"
            else:
                text += f" reset %{op.reset}, {op.reset_value}"
        return f"{text} : {_type_suffix(op.width)}"
    if isinstance(op, WireOp):
        source = getattr(op, "input_signal", "")
        return (f"%{op.result_name} = hw.wire %{source} : "
                f"{_type_suffix(op.bit_width())}")
    if isinstance(op, InstanceOp):
        inputs = ", ".join(f"{port}: %{signal}"
                           for port, signal in op.inputs.items())
        outputs = ", ".join(op.outputs)
        return (f'hw.instance "{op.instance_name}" @{op.module_name}'
                f"({inputs}) -> ({outputs})")
    if isinstance(op, CombOp):
        operands = ", ".join(f"%{name}" for name in op.operands)
        head = f"%{op.result_name} = {op.op_name}"
        if isinstance(op, ICmpOp):
            return (f"{head} {op.predicate} {operands} : "
                    f"{_type_suffix(op.width)}")
        if isinstance(op, ExtractOp):
            return (f"{head} {operands} from {op.low_bit} : "
                    f"{_type_suffix(op.width)}")
        if isinstance(op, ConcatOp):
            types = ", ".join(_type_suffix(w) for w in op.operand_widths)
            return f"{head} {operands} : {types}"
        return f"{head} {operands} : {_type_suffix(op.width)}"
    return f"// unprintable operation {op!r}"


def print_hw_module(module: HWModuleOp) -> str:
    """Re-emit `module` in CIRCT surface syntax."""
    widths: Dict[str, int] = dict(module.attributes.get("signal_widths", {}))
    ports: List[str] = []
    for port in module.ports:
        if port.is_output:
            ports.append(f"out {port.name}: {port.port_type}")
        else:
            ports.append(f"{port.direction.value} %{port.name}: {port.port_type}")
    lines = [f"hw.module @{module.name}({', '.join(ports)}) {{"]
    for op in module.body:
        lines.append("  " + _op_text(op, widths))
    lines.append("}")
    return "\n".join(lines) + "\n"


def print_circuit(circuit: Circuit) -> str:
    """Re-emit every module of `circuit`."""
    return "\n".join(print_hw_module(module) for module in circuit.modules)

