"""Verilog export: lower `hw`/`comb`/`seq` designs onto the SV dialect.

This mirrors CIRCT's ExportVerilog at a small scale: each combinational
operation becomes a `sv.assign`, each register becomes an `sv.alwaysff` block,
and the module boundary becomes an :class:`circt.sv_dialect.SVModuleOp`.
"""
from __future__ import annotations
from typing import Any, Dict, List

from .comb_dialect import (
    AddOp, AndOp, CombOp, ConcatOp, ExtractOp, ICmpOp, MulOp, MuxOp, OrOp,
    ShlOp, ShrUOp, SubOp, XorOp,
)
from .hw_dialect import ConstantOp, HWModuleOp, InstanceOp, OutputOp, WireOp
from .seq_dialect import CompRegClockEnabledOp, CompRegOp, FirRegOp
from .sv_dialect import AlwaysFFOp, AssignOp, SVModuleOp, SVRegOp, SVWireOp

#: Infix Verilog spelling of the binary comb operations.
_BINARY_OPERATORS: Dict[type, str] = {
    AddOp: "+", SubOp: "-", MulOp: "*", AndOp: "&", OrOp: "|", XorOp: "^",
    ShlOp: "<<", ShrUOp: ">>",
}

#: Verilog comparison operators, keyed by ``comb.icmp`` predicate.
_COMPARISONS: Dict[str, str] = {
    "eq": "==", "ne": "!=", "slt": "<", "sle": "<=", "sgt": ">", "sge": ">=",
    "ult": "<", "ule": "<=", "ugt": ">", "uge": ">=",
}


def _expression(op: CombOp) -> str:
    """Verilog right-hand side for a combinational operation."""
    operands = [f"{name}" for name in op.operands]
    operator = _BINARY_OPERATORS.get(type(op))
    if operator is not None and len(operands) >= 2:
        return f" {operator} ".join(operands)
    if isinstance(op, ICmpOp):
        symbol = _COMPARISONS.get(op.predicate, "==")
        return f"{operands[0]} {symbol} {operands[1]}"
    if isinstance(op, MuxOp):
        return f"{operands[0]} ? {operands[1]} : {operands[2]}"
    if isinstance(op, ConcatOp):
        return "{" + ", ".join(operands) + "}"
    if isinstance(op, ExtractOp):
        high = op.low_bit + op.width - 1
        return f"{operands[0]}[{high}:{op.low_bit}]"
    return operands[0] if operands else "'0"


def to_sv_module(module: HWModuleOp) -> SVModuleOp:
    """Lower an :class:`HWModuleOp` to an :class:`SVModuleOp`."""
    widths: Dict[str, int] = dict(module.attributes.get("signal_widths", {}))
    ports: List[Dict[str, Any]] = []
    for port in module.ports:
        direction = "output" if port.is_output else (
            "inout" if port.is_inout else "input")
        ports.append({"name": port.name, "width": port.bit_width(),
                      "direction": direction})
    body: List[Any] = []
    for op in module.body:
        if isinstance(op, ConstantOp):
            body.append(SVWireOp(name=op.result_name, width=op.width))
            body.append(AssignOp(target=op.result_name,
                                 expression=f"{op.width}'d{op.evaluate()}"))
        elif isinstance(op, (CompRegOp, CompRegClockEnabledOp, FirRegOp)):
            name = getattr(op, "result_name", "") or op.name
            body.append(SVRegOp(name=name, width=op.width))
            statements = [f"{name} <= {getattr(op, 'input_signal', '')};"]
            if isinstance(op, CompRegClockEnabledOp):
                statements = [f"if ({op.clock_enable}) {name} <= {op.input_signal};"]
            reset_body: List[str] = []
            if getattr(op, "reset", None):
                reset_signal = getattr(op, "reset_value_signal", None)
                reset_expr = reset_signal or f"{op.width}'d{op.reset_value}"
                reset_body = [f"{name} <= {reset_expr};"]
            body.append(AlwaysFFOp(clock=op.clock, reset=getattr(op, "reset", None),
                                   body=statements, reset_body=reset_body))
        elif isinstance(op, WireOp):
            body.append(SVWireOp(name=op.result_name, width=op.bit_width()))
            body.append(AssignOp(target=op.result_name,
                                 expression=getattr(op, "input_signal", "")))
        elif isinstance(op, CombOp):
            width = widths.get(op.result_name, op.width)
            body.append(SVWireOp(name=op.result_name, width=width))
            body.append(AssignOp(target=op.result_name, expression=_expression(op)))
        elif isinstance(op, OutputOp):
            for index, port in enumerate(module.output_ports):
                if index < len(op.operands):
                    body.append(AssignOp(target=port.name,
                                         expression=op.operands[index]))
        elif isinstance(op, InstanceOp):
            connections = ", ".join(f".{port}({signal})"
                                    for port, signal in op.inputs.items())
            body.append(AssignOp(
                target=f"// {op.instance_name}",
                expression=f"{op.module_name}({connections})"))
    return SVModuleOp(name=module.name, ports=ports, body=body)


def export_verilog(module: HWModuleOp) -> str:
    """Emit SystemVerilog text for `module`."""
    return to_sv_module(module).emit()

