module ALU (
  input [3:0] a,
  input [3:0] b,
  input [1:0] op,
  output [3:0] result
);
  wire [3:0] add_r;
  assign add_r = a + b;
  wire [3:0] and_r;
  assign and_r = a & b;
  wire [3:0] or_r;
  assign or_r = a | b;
  wire [3:0] xor_r;
  assign xor_r = a ^ b;
  wire [1:0] c0;
