  wire [1:0] c1;
  assign c1 = 2'd1;
  wire [1:0] c2;
  assign c2 = 2'd2;
  wire is_add;
  assign is_add = op == c0;
  wire is_and;
  assign is_and = op == c1;
  wire is_or;
  assign is_or = op == c2;
  wire [3:0] mux1;
  assign mux1 = is_or ? or_r : xor_r;
  wire [3:0] mux2;
  assign mux2 = is_and ? and_r : mux1;
  assign result = is_add ? add_r : mux2;
